    'Naam, bv. Home Assistant' => 'Name, e.g. Home Assistant',
    'Wachtwoord (min. 8 tekens)' => 'Password (min. 8 characters)',
    'E-mailadres (optioneel, voor wachtwoord vergeten)' => 'Email address (optional, for forgotten password)',
    '⛔ IP blokkeren' => '⛔ Block IP',
    '⚠️ Incidenten' => '⚠️ Incidents',
    '🔑 Toegang' => '🔑 Access',
