    'Lokaal = disk/services van deze monitor-server. Agent = remote server die disk/services rapporteert via rzmon-agent.sh. Remote = alleen ping/poort/http.' => 'Local = disk/services of this monitoring server. Agent = remote server that reports disk/services via rzmon-agent.sh. Remote = ping/port/http only.',
    'Afhankelijk van' => 'Depends on',
