    'Verwacht' => 'Expected',
    '✓ De <b>status</b> wordt altijd bewaakt: gestopt of ongezond = CRITICAL, gepauzeerd of net automatisch herstart = WARNING. Vink aan wat je daarnaast wilt bewaken:' => '✓ The <b>status</b> is always monitored: stopped or unhealthy = CRITICAL, paused or just restarted automatically = WARNING. Tick what else you want to monitor:',
    'Warning vanaf' => 'Warning from',
    'Critical vanaf' => 'Critical from',
    'Warning onder' => 'Warning below',
    'Critical onder' => 'Critical below',
    'CPU: 100% = één volledige core. RAM: percentage van de geheugenlimiet van de container. Disk: schrijflaag plus volumes.' => 'CPU: 100% = one full core. RAM: percentage of the container\'s memory limit. Disk: writable layer plus volumes.',
    'Services op deze server ophalen…' => 'Fetching services on this server…',
    'Status als de check slaagt' => 'Status if the check succeeds',
