    '<b class="warn-txt">⚠️ Heeft root nodig</b>, en commando\'s op {name} staan {mode}: zet ze op <i>als root</i> (Agent Manager), anders mislukt hij.' => '<b class="warn-txt">⚠️ Needs root</b>, and commands on {name} are set to {mode}: set them to <i>as root</i> (Agent Manager), otherwise it will fail.',
    'Werkt als nobody.' => 'Works as nobody.',
