    'Gestopte add-ons met exitcode 0 zijn bewust uitgezet; een add-on met een fout staat als gestopt (exit 1).' => 'Stopped add-ons with exit code 0 were deliberately turned off; an add-on with an error shows as stopped (exit 1).',
