    'Nog geen sleutels.' => 'No keys yet.',
    'Met het recht <b>⛔ IDS blokkeren</b> kan wie deze sleutel heeft IP-adressen blokkeren op je servers (als het IDS op <i>blokkeren</i> staat; in de leerstand wordt het alleen vastgelegd). Je LAN, RzMon zelf en de lijst <i>Nooit blokkeren</i> weigert de API altijd. Overweeg <i>Alleen vanaf</i> in te vullen.' => 'With the <b>⛔ Block via IDS</b> right, whoever has this key can block IP addresses on your servers (if the IDS is set to <i>blocking</i>; in learning mode it is only recorded). The API always refuses your LAN, RzMon itself and the <i>Never block</i> list. Consider filling in <i>Only from</i>.',
