    '<code>GET /vulnerabilities/{id}</code> – de kwetsbaarheden van één server (<code>?all=1</code>: ook geaccepteerde)' => '<code>GET /vulnerabilities/{id}</code> – the vulnerabilities of one server (<code>?all=1</code>: including accepted ones)',
