    'Bijwerken via de agent kan hier niet: {why}. Voer het commando hierboven zelf uit op de server.' => 'Updating via the agent is not possible here: {why}. Run the command above yourself on the server.',
    'Bijwerken via de agent' => 'Update via the agent',
    'Omschrijving' => 'Description',
    'Zo los je het op' => 'How to fix it',
    'Installeer de nieuwe versie uit de eigen pakketbron van de distributie (zoals hieronder); een download bij de maker is daarvoor niet nodig. Bij de kernel of een bibliotheek is daarna een herstart van de server of van de services nodig.' => 'Install the new version from the distribution\'s own package repository (as below); a download from the vendor is not needed. For the kernel or a library, a restart of the server or the services is needed afterwards.',
    'Meer informatie en adviezen' => 'More information and advisories',
    'Risico accepteren…' => 'Accept risk…',
    'Risico accepteren: {cve}' => 'Accept risk: {cve}',
    'Een geaccepteerde kwetsbaarheid telt niet meer mee en geeft geen melding. Je ziet hem terug onder het filter Geaccepteerd.' => 'An accepted vulnerability no longer counts and gives no notification. You will find it under the Accepted filter.',
    'Waarvoor' => 'For',
    '(bv. niet bereikbaar van buitenaf)' => '(e.g. not reachable from outside)',
    'Accepteren' => 'Accept',
    'Alle beveiligingsupdates installeren op {name}' => 'Install all security updates on {name}',
    'Bijwerken op {name}' => 'Update on {name}',
    'De agent installeert de nieuwe versie van alle pakketten waarvoor een oplossing is.' => 'The agent installs the new version of all packages that have a fix.',
    'De agent installeert de nieuwe versie van: {p}' => 'The agent installs the new version of: {p}',
    'Dit gebeurt bij het volgende rapport van de agent, met de pakketbeheerder van de server (dnf of apt), en komt in het logboek. Er wordt niets herstart; is dat nodig, dan zie je ↻ bij de server.' => 'This happens at the agent\'s next report, using the server\'s package manager (dnf or apt), and is recorded in the log. Nothing is restarted; if that is needed, you will see ↻ at the server.',
    'Bijwerken via de agent kan hier niet: {why}.' => 'Updating via the agent is not possible here: {why}.',
