    'RzMon is tijdens het installeren even niet bereikbaar. Dit venster laat zien hoe ver de installatie is.' => 'RzMon is briefly unavailable during the installation. This window shows how far the installation has got.',
    'Bijgewerkt naar {v}. De pagina wordt zo herladen…' => 'Updated to {v}. The page will reload shortly…',
