    'Nieuwe sleutel genereren' => 'Generate new key',
    'Kenmerk' => 'Fingerprint',
    'de vorige sleutel geldt nog tot {t}' => 'the previous key stays valid until {t}',
    'Nog geen sleutel: de agents versturen alles onversleuteld.' => 'No key yet: the agents send everything unencrypted.',
    'Agent' => 'Agent',
    'Versleuteld versturen' => 'Send encrypted',
    'Laatste rapport' => 'Last report',
    'IP-adres of netwerk' => 'IP address or network',
    'Blokkade opheffen' => 'Remove block',
    'Nog niets geblokkeerd. Je eigen IP-adres is {ip}.' => 'Nothing blocked yet. Your own IP address is {ip}.',
    'Er komt een nieuwe sleutel. De agents krijgen hem bij hun volgende rapport (versleuteld met de huidige); de huidige sleutel blijft nog <b>24 uur</b> geldig, zodat er niets misgaat. Een agent die langer offline is, krijgt de nieuwe bij zijn eerste onversleutelde rapport, of geef hem mee met <code>--key</code>.' => 'A new key will be created. The agents receive it with their next report (encrypted with the current one); the current key stays valid for <b>24 hours</b>, so nothing breaks. An agent that is offline for longer gets the new key with its first unencrypted report, or pass it with <code>--key</code>.',
    'RzMon maakt een willekeurige sleutel van 32 bytes. De agents (1.49.0 of nieuwer) krijgen hem bij hun volgende rapport en versturen daarna alles versleuteld.' => 'RzMon creates a random 32-byte key. The agents (1.49.0 or newer) receive it with their next report and send everything encrypted from then on.',
    'Genereren' => 'Generate',
    'Nieuwe sleutel opgeslagen' => 'New key saved',
    'Opgeslagen; de agent pakt het op bij zijn volgende rapport' => 'Saved; the agent picks it up with its next report',
    'Blokkade opgeheven' => 'Block lifted',
    '{ip} blokkeren' => 'Block {ip}',
    'Een geblokkeerd adres krijgt nergens meer toegang tot RzMon: niet de webpagina, niet het inloggen, niet de API en geen agents.' => 'A blocked address gets no access to RzMon at all: not the web page, not the login, not the API and no agents.',
    'Alleen dit adres' => 'Only this address',
    'Het hele netwerk' => 'The whole network',
    'vanuit Meldingen' => 'from Alerts',
    'Aan (oude agents mogen nog onversleuteld)' => 'On (old agents may still send unencrypted)',
    'Verplicht' => 'Required',
    'verplicht' => 'required',
    'nog geen rapport' => 'no report yet',
    'laatste rapport versleuteld' => 'last report encrypted',
    'laatste rapport niet versleuteld' => 'last report not encrypted',
    'Versleuteld versturen:' => 'Send encrypted:',
    'geblokkeerd' => 'blocked',
    'wachtwoord en 2FA' => 'password and 2FA',
    'onthouden apparaat' => 'remembered device',
    'onbekende gebruiker' => 'unknown user',
    'verkeerde 2FA-code' => 'wrong 2FA code',
    'geen token meegestuurd' => 'no token sent',
    'onbekend token (verkeerd gekopieerd, of in RzMon vernieuwd?)' => 'unknown token (copied wrongly, or renewed in RzMon?)',
    'Niet verstuurd: alleen op deze pagina (zie de meldregels)' => 'Not sent: only on this page (see the notification rules)',
    'Dit account is geblokkeerd na te veel mislukte pogingen. Vraag een beheerder om het te deblokkeren.' => 'This account is locked after too many failed attempts. Ask an administrator to unlock it.',
    'Inlogbeveiliging' => 'Login protection',
    'Na' => 'After',
    'mislukte pogingen binnen' => 'failed attempts within',
    'minuten:' => 'minutes:',
    'het <b>account</b> blokkeren' => 'lock the <b>account</b>',
    'het <b>IP-adres</b> blokkeren (niet als het uit je lokale netwerken komt)' => 'block the <b>IP address</b> (not if it comes from your local networks)',
    'Blokkade opheffen na' => 'Lift the block after',
    '(0 = tot een beheerder deblokkeert)' => '(0 = until an administrator unlocks it)',
    'Een verkeerde 2FA-code telt ook. Pogingen tellen apart per account (vanaf welk IP dan ook) en per IP-adres. Een geblokkeerd account kan vanaf je <b>lokale netwerk</b> gewoon inloggen, zodat niemand van buiten je kan buitensluiten. Je krijgt een ⚠️-melding met Pushover. Deblokkeren: bij <i>Gebruikers</i> (🔓) en bij <i>Blokkades</i>; of op de server <code>sudo php install/install.php --unlock &lt;gebruiker&gt;</code>.' => 'A wrong 2FA code also counts. Attempts are counted separately per account (from any IP) and per IP address. A locked account can still log in from your <b>local network</b>, so nobody outside can lock you out. You get a ⚠️ alert with Pushover. Unlock: under <i>Users</i> (🔓) and <i>Blocks</i>; or on the server <code>sudo php install/install.php --unlock &lt;user&gt;</code>.',
    'account {user} geblokkeerd' => 'account {user} locked',
    'automatisch: {n} mislukte logins ({user})' => 'automatic: {n} failed logins ({user})',
