    'Klik op een punt om het meteen te regelen. Grijze punten zijn optioneel en tellen niet mee.' => 'Click an item to fix it right away. Grey items are optional and do not count.',
    'meer uitleg' => 'more',
    'minder' => 'less',
    'CVE\'s' => 'CVEs',
    'onbekende sleutel (vernieuwd of opnieuw gekoppeld?): koppel de agent opnieuw met een koppelcode' => 'unknown key (renewed or paired again?): pair the agent again with a pairing code',
    'alleen een token, maar deze server heeft een eigen sleutel: koppel de agent opnieuw met een koppelcode' => 'only a token, but this host has its own key: pair the agent again with a pairing code',
    'nieuw IP-adres {ip} (bekend: {known}); toestaan kan bij Instellingen → Agents → Standaardinstellingen' => 'new IP address {ip} (known: {known}); you can allow it under Settings → Agents → Default settings',
    'onversleuteld bericht met een sleutelkenmerk' => 'unencrypted message with a key id',
    'ongeldige of verlopen koppelcode' => 'invalid or expired pairing code',
    'Agent gekoppeld: {name}' => 'Agent paired: {name}',
    'Agent op {name} is gekoppeld met een koppelcode en heeft een eigen sleutel' => 'Agent on {name} was paired with a pairing code and has its own key',
    'Eigen sleutel per agent' => 'Own key per agent',
    '{n} nog zonder eigen sleutel: {names} (agent {v} nodig; anders opnieuw koppelen)' => '{n} still without their own key: {names} (agent {v} needed; otherwise pair again)',
    'alle agents hebben een eigen sleutel' => 'all agents have their own key',
    'Agent van een nieuw IP-adres' => 'Agent from a new IP address',
    'geweigerd, wacht op je toestemming: {names}' => 'refused, waiting for your approval: {names}',
    'Deze server heeft nog geen eigen sleutel' => 'This host does not have its own key yet',
    'Er wacht geen nieuw IP-adres' => 'No new IP address is waiting',
    'Beveiligde verbinding met de agents' => 'Secure connection with the agents',
    'Elke agent (1.50.0 of nieuwer) heeft een <b>eigen sleutel</b>. Daarmee is alles wat hij verstuurt versleuteld en ondertekend (AES-256 met een handtekening), ook het antwoord van RzMon. Er gaat geen token meer over de lijn, en een sleutel nooit leesbaar: een nieuwe agent koppel je met een <b>koppelcode</b> (Agent Manager → 🔗 Koppelcode, eenmalig en 15 minuten geldig). Agents die al met de algemene sleutel werkten, krijgen hun eigen sleutel vanzelf. Een bericht met een verkeerde sleutel, een oude handtekening of van een onbekend IP-adres wordt geweigerd en geeft een ⚠️-melding.' => 'Every agent (1.50.0 or newer) has its <b>own key</b>. Everything it sends is encrypted and signed with it (AES-256 with a signature), and so is the answer from RzMon. No token travels over the line any more, and a key never in readable form: you pair a new agent with a <b>pairing code</b> (Agent Manager → 🔗 Pairing code, single use and valid for 15 minutes). Agents that already used the general key get their own key automatically. A message with a wrong key, an old signature or from an unknown IP address is refused and raises a ⚠️ alert.',
    'Sleutels van de agents vernieuwen' => 'Renew the agents\' keys',
    'elke 7 dagen' => 'every 7 days',
    'elke 30 dagen' => 'every 30 days',
    'elke 90 dagen' => 'every 90 days',
    'alleen met de hand' => 'manually only',
    '📌 <b>Certificaat van RzMon vastzetten</b> (bij een eigen, self-signed certificaat)' => '📌 <b>Pin RzMon\'s certificate</b> (with an own, self-signed certificate)',
    '🌐 Agents alleen vanaf hun <b>bekende IP-adres</b>' => '🌐 Agents only from their <b>known IP address</b>',
    'Het eerste IP-adres van een agent wordt onthouden. Komt hij van een ander adres, dan weigert RzMon hem en krijg je een melding; hierboven kun je het nieuwe adres dan <b>toestaan</b>.' => 'The first IP address of an agent is remembered. If it comes from another address, RzMon refuses it and you get an alert; you can then <b>allow</b> the new address above.',
    'Algemene sleutel (agents 1.49.x)' => 'General key (agents 1.49.x)',
    'Agents van versie 1.49.x versleutelen met één algemene sleutel. Nieuwere agents gebruiken die alleen nog om over te stappen op hun eigen sleutel.' => 'Agents of version 1.49.x encrypt with one general key. Newer agents only use it to switch to their own key.',
    '(64 tekens)' => '(64 characters)',
    'handtekening onvolledig' => 'signature incomplete',
    'Uit: agents met <code>INSECURE=1</code> accepteren elk certificaat.' => 'Off: agents with <code>INSECURE=1</code> accept any certificate.',
    'Vingerafdruk van RzMon' => 'RzMon\'s fingerprint',
    'de agents krijgen hem vanzelf (versleuteld); bij een nieuw certificaat controleren ze het met hun sleutel' => 'the agents get it automatically (encrypted); with a new certificate they verify it with their key',
    'Niet nodig: het certificaat van RzMon is geldig (bekende uitgever), de agents controleren het gewoon.' => 'Not needed: RzMon\'s certificate is valid (known issuer); the agents simply verify it.',
    'Niet nodig: je opent RzMon via http. Met https en een eigen certificaat zet RzMon het vanzelf vast.' => 'Not needed: you open RzMon over http. With https and an own certificate RzMon pins it automatically.',
    'De vingerafdruk is nog niet te bepalen (bv. achter een proxy); dat gebeurt bij het volgende rapport van een agent.' => 'The fingerprint cannot be determined yet (e.g. behind a proxy); that happens with the next report of an agent.',
    '<b>{name}</b> wil verbinden vanaf <code>{ip}</code> en is geweigerd (bekend: {known}).' => '<b>{name}</b> wants to connect from <code>{ip}</code> and was refused (known: {known}).',
    'eigen sleutel' => 'own key',
    '{n} d oud' => '{n} d old',
    'koppelcode klaar' => 'pairing code ready',
    'agent {v} nodig' => 'agent {v} needed',
    'nog geen eigen sleutel' => 'no own key yet',
    'nog niet bekend' => 'not known yet',
    'Vergeten: het volgende IP-adres van deze agent wordt het bekende' => 'Forget: the next IP address of this agent becomes the known one',
    'Koppelcode maken en de agent (opnieuw) koppelen' => 'Create a pairing code and pair the agent (again)',
    'Nieuwe sleutel; de agent krijgt hem bij zijn volgende rapport' => 'New key; the agent gets it with its next report',
    'Minder veilig maken?' => 'Make it less secure?',
    'Zonder vastgezet certificaat accepteren agents met <code>INSECURE=1</code> elk certificaat, ook dat van een nep-RzMon.' => 'Without a pinned certificate, agents with <code>INSECURE=1</code> accept any certificate, including that of a fake RzMon.',
    'Agents worden dan vanaf elk IP-adres geaccepteerd (met hun sleutel).' => 'Agents are then accepted from any IP address (with their key).',
    'Uitzetten' => 'Turn off',
    '{ip} toegestaan; de agent komt bij zijn volgende rapport weer binnen' => '{ip} allowed; the agent gets in again with its next report',
    'Nieuwe sleutel voor deze agent? Hij krijgt hem bij zijn volgende rapport; de huidige blijft nog 24 uur geldig.' => 'New key for this agent? It gets it with its next report; the current one stays valid for 24 hours.',
    'Nieuwe sleutel klaar' => 'New key ready',
    'Bekende IP-adressen van deze agent vergeten? Het volgende adres waarvan hij rapporteert, wordt het bekende.' => 'Forget the known IP addresses of this agent? The next address it reports from becomes the known one.',
    'Koppelcode maken' => 'Create pairing code',
    'Eenmalig en 15 minuten geldig. De agent haalt er zijn eigen sleutel mee op; er gaat geen token of sleutel leesbaar over de lijn.' => 'Single use and valid for 15 minutes. The agent fetches its own key with it; no token or key travels over the line in readable form.',
    'nog geen eigen sleutel: maak hieronder een koppelcode' => 'no own key yet: create a pairing code below',
    'Geweigerd vanaf het nieuwe IP-adres <code>{ip}</code>. Toestaan kan bij Instellingen → Agents → Standaardinstellingen.' => 'Refused from the new IP address <code>{ip}</code>. You can allow it under Settings → Agents → Default settings.',
    'Maak een koppelcode en voer het commando uit:' => 'Create a pairing code and run the command:',
    'Tabblad <b>Configuratie</b>: vul de koppelcode in (eenmalig, 15 minuten geldig):' => '<b>Configuration</b> tab: enter the pairing code (single use, valid for 15 minutes):',
    'Oude manier: met het token (agent ouder dan 1.50.0)' => 'Old way: with the token (agent older than 1.50.0)',
    'Zonder koppelcode: de agent stuurt dan zijn token mee. Een agent van 1.50.0 of nieuwer krijgt bij zijn eerste versleutelde rapport alsnog een eigen sleutel.' => 'Without a pairing code the agent sends its token. An agent of 1.50.0 or newer still gets its own key with its first encrypted report.',
    'Koppelcode' => 'Pairing code',
    'Opslaan en de add-on (her)starten. In het logboek moet <code>Gekoppeld met RzMon</code> staan.' => 'Save and (re)start the add-on. The log should show <code>Gekoppeld met RzMon</code>.',
    'Het commando controleert eerst het installatiescript en de agent (SHA-256)' => 'The command first verifies the install script and the agent (SHA-256)',
