    'Adressen getroffen' => 'Addresses affected',
    'Afgehandeld' => 'Handled',
    'laatste controle {t}' => 'last check {t}',
    'dagelijks' => 'daily',
    'Geen API-sleutel: alleen de wachtwoorden van RzMon-accounts worden gecontroleerd. Een sleutel vul je in bij Instellingen → Beveiliging → Datalekken.' => 'No API key: only the passwords of RzMon accounts are checked. Enter a key under Settings → Security → Data breaches.',
