    'op geen enkele server gevonden' => 'not found on any server',
    'SWAG: veel 404 (zoekt naar lekken)' => 'SWAG: many 404s (searching for holes)',
    'SWAG: veel 401/403 (raadt wachtwoorden)' => 'SWAG: many 401/403s (guessing passwords)',
    'SWAG: verzoeken zonder bekende hostnaam (scant je IP-adres)' => 'SWAG: requests without a known host name (scanning your IP address)',
    '🔁 Andere versie…' => '🔁 Other version…',
    'Onbekende versie: {v}' => 'Unknown version: {v}',
    'Deze versie is al geïnstalleerd' => 'This version is already installed',
    'Heartbeat' => 'Heartbeat',
    'Je hebt bewust versie {v} gekozen: automatisch bijwerken staat op pauze tot je weer naar de nieuwste gaat.' => 'You deliberately chose version {v}: automatic updating is paused until you go back to the latest.',
    '(niets kiezen = de nieuwste)' => '(choose nothing = the latest)',
    'De nieuwste ({v})' => 'The latest ({v})',
    'ouder: terugzetten' => 'older: roll back',
    '⚠️ <b>Terugzetten naar een oudere versie.</b> Je instellingen en gegevens blijven staan; de database blijft zoals hij is (nieuwere kolommen worden niet gebruikt). Wat er sindsdien bij kwam, werkt niet meer. Automatisch bijwerken pauzeert tot je weer naar de nieuwste gaat. Agents hoef je niet terug te zetten.' => '⚠️ <b>Rolling back to an older version.</b> Your settings and data stay; the database stays as it is (newer columns are not used). What was added since then no longer works. Automatic updating pauses until you go back to the latest. You don\'t need to roll back the agents.',
    'TERUGZETTEN' => 'ROLLBACK',
    '{n} seconden' => '{n} seconds',
    '1 minuut' => '1 minute',
    'huidig' => 'current',
    'Interval' => 'Interval',
    'Achtergrondtaken' => 'Background tasks',
    'alles loopt' => 'everything is running',
    'Verbindingen en taken' => 'Connections and tasks',
    'Wat er bij RzMon binnenkomt en wat RzMon zelf op de achtergrond doet. Lukt een taak te lang niet, dan krijg je een ⚠️-melding (Meldingen → Systeeminfo → Achtergrondtaak lukt niet).' => 'What connects to RzMon and what RzMon itself does in the background. If a task keeps failing for too long, you get a ⚠️ alert (Notifications → System info → Background task failing).',
    'Checks uitvoeren (cron)' => 'Running checks (cron)',
    'elke minuut' => 'every minute',
    'Als dit stilstaat, gebeurt er niets meer: geen checks en geen meldingen.' => 'If this stops, nothing happens any more: no checks and no alerts.',
    'Nieuwe versie zoeken (GitHub)' => 'Looking for a new version (GitHub)',
    'dagelijks; automatisch bijwerken om {t}' => 'daily; automatic update at {t}',
    'Blocklists van bekende aanvallers' => 'Blocklists of known attackers',
    'GeoIP-database (land per IP)' => 'GeoIP database (country per IP)',
    'maandelijks' => 'monthly',
    'dagelijks, verspreid' => 'daily, spread out',
    'Kwetsbaarheden zoeken (OSV, KEV, EPSS)' => 'Looking for vulnerabilities (OSV, KEV, EPSS)',
    'Certificaat van het beheeradres' => 'Certificate of the admin address',
    'MQTT naar Home Assistant' => 'MQTT to Home Assistant',
    'elke minuut; discovery elk uur' => 'every minute; discovery every hour',
    'Automatische back-up' => 'Automatic backup',
    'wekelijks' => 'weekly',
    'Meldt zichzelf al als hij mislukt.' => 'Already sends its own alert when it fails.',
    'Laatst gelukt: {t}.' => 'Last succeeded: {t}.',
    'Nog nooit gelukt.' => 'Never succeeded yet.',
    '{task} lukt niet' => '{task} is failing',
    'Fout: {e}' => 'Error: {e}',
    'Zie Instellingen → Systeem → Verbindingen en taken.' => 'See Settings → System → Connections and tasks.',
    '{task} lukt weer' => '{task} works again',
    'De taak is weer gelukt.' => 'The task succeeded again.',
    'Achtergrondtaak lukt niet (en weer gelukt)' => 'Background task failing (and working again)',
    'loopt' => 'running',
    'laatste poging mislukt' => 'last attempt failed',
    'lukt niet' => 'failing',
    'nog niet gedaan' => 'not done yet',
    'Binnenkomend' => 'Incoming',
    'Starten elke 30 s en sturen een rapport als hun ritme om is (standaard {t}, per server in te stellen in de Agent Manager). Met realtime gaat er bij een login, een gestopte service of een gewijzigd bestand meteen een rapport uit.' => 'Start every 30 s and send a report when their interval is up (default {t}, adjustable per server in the Agent Manager). With real-time, a login, a stopped service or a changed file sends a report right away.',
    'Ritme' => 'Interval',
    'Realtime' => 'Real-time',
    'Geen agents.' => 'No agents.',
    'Browsers (laatste 24 uur)' => 'Browsers (last 24 hours)',
    'Een geopend tabblad ververst elke 20 s, alleen als het zichtbaar is.' => 'An open tab refreshes every 20 s, only while it is visible.',
    'Geen.' => 'None.',
    'Wanneer iets erom vraagt, bijvoorbeeld REST-sensoren in Home Assistant.' => 'Whenever something asks, for example REST sensors in Home Assistant.',
    'Heartbeats' => 'Heartbeats',
    'Wanneer je scripts, cronjobs of apparaten zich melden.' => 'Whenever your scripts, cron jobs or devices check in.',
    'Laatst gemeld' => 'Last check-in',
    'Achtergrondtaken van RzMon' => 'RzMon background tasks',
    'RzMon draait elke minuut (cron): checks naar je apparaten volgens hun interval, meldingen naar Pushover, e-mail en Home Assistant, en deze taken.' => 'RzMon runs every minute (cron): checks to your devices according to their interval, alerts to Pushover, e-mail and Home Assistant, and these tasks.',
    'Taak' => 'Task',
    'Hoe vaak' => 'How often',
    'Laatst gelukt' => 'Last succeeded',
    'Volgende' => 'Next',
    'Stand' => 'State',
    '{n} sessies' => '{n} sessions',
    'Kwetsbaarheden staat uit (Instellingen → Beveiliging → Kwetsbaarheden)' => 'Vulnerabilities are off (Settings → Security → Vulnerabilities)',
    'IDS: detectie' => 'IDS: detection',
    'je LAN en RzMon zelf worden nooit automatisch geblokkeerd. Andere IP-adressen en netwerken zet je op de <a href="#ids/blk" data-goto="ids/blk">✅ whitelist</a>; die geldt voor RzMon én het IDS op al je servers.' => 'your LAN and RzMon itself are never blocked automatically. Put other IP addresses and networks on the <a href="#ids/blk" data-goto="ids/blk">✅ whitelist</a>; it applies to RzMon and to the IDS on all your hosts.',
    'IDS: aanvallers en verkeer' => 'IDS: attackers and traffic',
    'Werkt alleen als het IDS aan staat (<a href="#settings/ids" data-goto="settings/ids">IDS: detectie</a>).' => 'Only works when the IDS is on (<a href="#settings/ids" data-goto="settings/ids">IDS: detection</a>).',
    'IDS: servers' => 'IDS: hosts',
    'Per server (sleutel, IP-adres, verbinding): zie de tabel bij <a href="#settings/agents" data-goto="settings/agents">Agents</a>.' => 'Per host (key, IP address, connection): see the table under <a href="#settings/agents" data-goto="settings/agents">Agents</a>.',
    'Databaseverbinding' => 'Database connection',
    'Waar RzMon zijn gegevens bewaart (MariaDB of MySQL). Alleen aanpassen als je de database verhuist; opslaan vraagt je wachtwoord en installeert de tabellen op de nieuwe plek.' => 'Where RzMon stores its data (MariaDB or MySQL). Only change this when you move the database; saving asks for your password and installs the tables in the new place.',
    'Server en PHP' => 'Server and PHP',
    'Systeemcheck' => 'System check',
    'Databasewachtwoord' => 'Database password',
    'Deze API-sleutel is verlopen op {date}; verleng hem in RzMon (Instellingen → Koppelingen → API-sleutels)' => 'This API key expired on {date}; extend it in RzMon (Settings → Integrations → API keys)',
    '{net} staat op de whitelist (IDS → Blokkades); haal het daar eerst af' => '{net} is on the whitelist (IDS → Blocks); remove it there first',
    'Zie Instellingen → Overzicht → Verbindingen en taken.' => 'See Settings → Overview → Connections and tasks.',
    'De agent voert een commando uit op de server, en RzMon vergelijkt de uitvoer met het antwoord dat je verwacht. Alleen als commando\'s voor deze server aan staan (Instellingen → Agents → Commando-checks).' => 'The agent runs a command on the host, and RzMon compares the output with the answer you expect. Only when commands are enabled for this host (Settings → Agents → Command checks).',
    'Extra paden voor deze server, bovenop de algemene lijst (<i>Instellingen → IDS → Algemeen</i>). Hetzelfde pad hier gaat voor, bv. om de ernst te veranderen.' => 'Extra paths for this host, on top of the general list (<i>Settings → IDS → General</i>). The same path here takes precedence, e.g. to change the severity.',
    '<b class="warn-txt">⚠️ Commando\'s staan voor {name} uit.</b> De check blijft onbekend tot je ze aanzet: Instellingen → Agents → Commando-checks, of per server in de Agent Manager.' => '<b class="warn-txt">⚠️ Commands are off for {name}.</b> The check stays unknown until you enable them: Settings → Agents → Command checks, or per host in the Agent Manager.',
    'Toegang bijhouden staat uit: er komt niets nieuws bij. Aanzetten onder <a href="#settings/ids" data-goto="settings/ids">Instellingen → IDS → Algemeen</a>.' => 'Access tracking is off: nothing new is added. Turn it on under <a href="#settings/ids" data-goto="settings/ids">Settings → IDS → General</a>.',
    'Een mislukte poging met meerdere gebruikers wordt alleen verborgen als <i>alle</i> gebruikers genegeerd worden, of het IP-adres. De lijst pas je aan onder <i>Instellingen → IDS → Algemeen → Negeren</i>. Brute-forcedetectie van het IDS blijft gewoon werken.' => 'A failed attempt with several users is only hidden when <i>all</i> users are ignored, or the IP address. You edit the list under <i>Settings → IDS → General → Ignore</i>. Brute-force detection of the IDS keeps working.',
    'Van buiten' => 'From outside',
    'Commando-checks' => 'Command checks',
    'Koppelingen' => 'Integrations',
    'REST API en API-sleutels' => 'REST API and API keys',
    'Database en opslag' => 'Database and storage',
    'In te stellen bij <a href="#settings/ids_attack" data-goto="settings/ids_attack">IDS: aanvallers en verkeer</a>. Zonder landgegevens geldt dit niet.' => 'Set under <a href="#settings/ids_attack" data-goto="settings/ids_attack">IDS: attackers and traffic</a>. Without country data this does not apply.',
    'Er zijn nog geen landgegevens (<a href="#settings/ids_attack" data-goto="settings/ids_attack">IDS: aanvallers en verkeer</a>); tot dan geldt dit niet.' => 'There is no country data yet (<a href="#settings/ids_attack" data-goto="settings/ids_attack">IDS: attackers and traffic</a>); until then this does not apply.',
    '{n} stil' => '{n} silent',
    'Realtime aan op: {names}.' => 'Real-time on for: {names}.',
    '{n} apparaten van 1 gebruiker' => '{n} devices of 1 user',
