    'Alle checks van deze server komen al uit een sjabloon.' => 'All checks of this host already come from a template.',
    'Sjabloon maken van een server' => 'Create template from a host',
    'Naam van het sjabloon' => 'Template name',
    'Het adres van de server wordt in het sjabloon <code>{adres}</code>, zodat het op elke server werkt. Deze server wordt meteen gekoppeld.' => 'The host address becomes <code>{adres}</code> in the template, so it works on every host. This host is linked right away.',
