    'De checks die uit dit sjabloon komen, blijven op de servers staan (los van het sjabloon), tenzij je hieronder kiest om ze ook te verwijderen.' => 'The checks from this template stay on the hosts (detached from the template), unless you choose below to delete them too.',
    'Sjabloon verwijderd' => 'Template deleted',
    'Check uit het sjabloon halen' => 'Remove check from the template',
    'De check verdwijnt uit het sjabloon. Op de servers blijft hij staan (los), tenzij je hieronder kiest om hem daar ook te verwijderen.' => 'The check is removed from the template. It stays on the hosts (detached), unless you choose below to delete it there too.',
