    'Checks uit een sjabloon gaan na aanpassen niet meer mee met het sjabloon.' => 'Checks from a template no longer follow the template after you change them.',
    '{n} checks bijgewerkt' => '{n} checks updated',
    'Interval voor {n} checks' => 'Interval for {n} checks',
    'Drempels voor {n} checks' => 'Thresholds for {n} checks',
