    'Melden voor {n} checks' => 'Alerting for {n} checks',
    'Melden na zoveel mislukte checks achter elkaar' => 'Alert after this many failed checks in a row',
    '(leeg = de algemene instelling)' => '(empty = the general setting)',
    'Eigen meldregels weghalen: de algemene meldregels gebruiken' => 'Remove own alert rules: use the general alert rules',
    'Alleen info (telt nooit als storing)' => 'Info only (never counts as an outage)',
