    'Onderhoud voor {n} checks' => 'Maintenance for {n} checks',
    '4 uur' => '4 hours',
    '{n} checks kopiëren naar…' => 'Copy {n} checks to…',
    'Elke gekozen server krijgt een kopie (los, niet uit een sjabloon). Staat het adres van de oorspronkelijke server in het doel, dan wordt dat het adres van de nieuwe server.' => 'Each chosen host gets a copy (detached, not from a template). If the target contains the address of the original host, it becomes the address of the new host.',
    'Kies minstens één server' => 'Choose at least one host',
    '{n} checks gekopieerd' => '{n} checks copied',
    '{n} checks verwijderen' => 'Delete {n} checks',
    'De checks en hun geschiedenis worden verwijderd. Checks uit een sjabloon komen niet terug, tenzij je de server opnieuw koppelt.' => 'The checks and their history are deleted. Checks from a template do not come back unless you link the host again.',
    '{n} checks verwijderd' => '{n} checks deleted',
    'Disk {m}' => 'Disk {m}',
    'Certificaat {n}' => 'Certificate {n}',
    'Poort {p}' => 'Port {p}',
    'Bereikbaar van buiten de server' => 'Reachable from outside the host',
    'Nog niet bewaakt: disks, services, containers, certificaten en poorten die de agent ziet' => 'Not monitored yet: disks, services, containers, certificates and ports the agent sees',
    '1 nieuw gevonden' => '1 new found',
    '{n} nieuw gevonden' => '{n} new found',
    'Nu proberen' => 'Try now',
    'Op een agent-server gebruikt RzMon het laatste rapport; een nieuwe service, log of commando ziet de agent pas bij zijn volgende rapport.' => 'On an agent host RzMon uses the latest report; the agent only sees a new service, log or command at its next report.',
    'Disks' => 'Disks',
    'Services' => 'Services',
    'Containers' => 'Containers',
    'Certificaten' => 'Certificates',
    'Nog niet bewaakt – {name}' => 'Not monitored yet – {name}',
    'Dit ziet de agent op de server, maar er is nog geen check voor. Vink aan wat je wilt bewaken; de rest kun je negeren, dan komt het niet meer terug.' => 'The agent sees this on the host, but there is no check for it yet. Tick what you want to monitor; you can ignore the rest so it does not come back.',
    'Alles wordt al bewaakt.' => 'Everything is already monitored.',
    '{n} genegeerd.' => '{n} ignored.',
    'Weer tonen' => 'Show again',
    'Gekozen negeren' => 'Ignore selected',
    'Niets gekozen' => 'Nothing selected',
    'Checks toevoegen' => 'Add checks',
    '1 check toegevoegd' => '1 check added',
    '{n} checks toegevoegd' => '{n} checks added',
    'Opschoonadvies' => 'Clean-up advice',
    'Checks die je aandacht verdienen: al dagen onbekend, de meeste meldingen (ruismakers), steeds wisselend, al lang in warning, net onder de drempel, of al lang uit. Met een voorstel; wat normaal is, zet je op "niet meer tonen".' => 'Checks that deserve your attention: unknown for days, the most alerts (noisy), constantly changing, in warning for a long time, just below the threshold, or off for a long time. With a suggestion; mark what is normal as "do not show again".',
    'Staat uit, al {n} dagen niet gecontroleerd' => 'Off, not checked for {n} days',
    'Nodig? Zet hem weer aan, of verwijder hem.' => 'Needed? Turn it back on, or delete it.',
    'Al {n} dagen ONBEKEND: {msg}' => 'UNKNOWN for {n} days: {msg}',
    'Bestaat het doel nog (service, container, disk, agent)? Pas de check aan of verwijder hem.' => 'Does the target still exist (service, container, disk, agent)? Adjust the check or delete it.',
    'Al {n} dagen WARNING ({value})' => 'WARNING for {n} days ({value})',
    'Is dit normaal voor deze server? Verhoog dan de warning-drempel; anders oplossen.' => 'Is this normal for this host? Then raise the warning threshold; otherwise fix it.',
    '{n} meldingen in 7 dagen' => '{n} alerts in 7 days',
    'Melden pas na 3 mislukte checks achter elkaar haalt korte haperingen weg; of verhoog de drempels.' => 'Alerting only after 3 failed checks in a row removes short hiccups; or raise the thresholds.',
    '{n} keer van status gewisseld in 7 dagen' => 'Changed status {n} times in 7 days',
    'Een langer interval of melden na een paar mislukte checks maakt hem rustiger; kijk ook of het doel echt hapert.' => 'A longer interval or alerting after a few failed checks makes it calmer; also check whether the target really falters.',
    'Gemiddeld {avg}, de warning-drempel is {w}' => 'Average {avg}, the warning threshold is {w}',
    'De waarde zit bijna altijd net onder de drempel: een kleine piek geeft al een melding. Verhoog de drempel iets, of los het op.' => 'The value is almost always just below the threshold: a small peak already causes an alert. Raise the threshold a little, or fix it.',
    'Al dagen onbekend' => 'Unknown for days',
    'Ruismakers' => 'Noisy checks',
    'Wisselt steeds' => 'Keeps changing',
    'Al lang in warning' => 'In warning for a long time',
    'Net onder de drempel' => 'Just below the threshold',
    'Al lang uit' => 'Off for a long time',
    'Melden na 3' => 'Alert after 3',
    'Dit is normaal: niet meer tonen' => 'This is normal: do not show again',
    'Niets op te ruimen. Alle checks zien er gezond uit.' => 'Nothing to clean up. All checks look healthy.',
    'Wordt niet meer getoond' => 'Will not be shown again',
