    'Grootste tabellen' => 'Largest tables',
    '{n} rijen' => '{n} rows',
    'Meethistorie en meldingen bewaren stel je in bij Database en opslag.' => 'Retention of history and alerts is set under Database and storage.',
    'Duur van een ronde' => 'Run duration',
    'Laatste {l} s · gemiddeld {a} s · langste {m} s (laatste {n} rondes)' => 'Last {l} s · average {a} s · longest {m} s (last {n} runs)',
    '{n} keer bijna een minuut of langer' => '{n} times almost a minute or longer',
