    'Nog niet gemeten.' => 'Not measured yet.',
    'Traagste checks' => 'Slowest checks',
    'Een trage check (time-out) houdt de rest van de ronde op. Kijk of het doel bereikbaar is, of geef hem een langer interval.' => 'A slow check (timeout) holds up the rest of the run. Check whether the target is reachable, or give it a longer interval.',
    'Geen trage checks (alles onder 0,1 seconde).' => 'No slow checks (everything under 0.1 seconds).',
