    'De netwerkscan staat uit.' => 'The network scan is off.',
    'Zet hem aan bij <a href="#settings/netscan" data-goto="settings/netscan">Instellingen → Beveiliging → Netwerkscan</a>.' => 'Turn it on under <a href="#settings/netscan" data-goto="settings/netscan">Settings → Security → Network scan</a>.',
    'Een beheerder kan hem aanzetten.' => 'An administrator can turn it on.',
    'Geen netwerk om te scannen: zet je netwerk (bv. 192.168.1.0/24) bij <a href="#settings/access" data-goto="settings/access">Toegang → Lokale netwerken</a>.' => 'No network to scan: add your network (e.g. 192.168.1.0/24) under <a href="#settings/access" data-goto="settings/access">Access → Local networks</a>.',
