    'Heb je deze dienst niet nodig, zet hem dan uit in de instellingen van het apparaat. Anders: zorg voor een sterk wachtwoord en laat de poort nooit van internet bereikbaar zijn.' => 'If you don\'t need this service, turn it off in the device\'s settings. Otherwise: use a strong password and never make the port reachable from the internet.',
