    '(Network 9 of nieuwer: alleen lezen, weren kan dan niet)' => '(Network 9 or newer: read only, blocking is then not possible)',
    '(uit bij het eigen certificaat van UniFi)' => '(off for UniFi\'s own certificate)',
    'Maak in UniFi een <b>lokaal account</b> voor RzMon (<i>Admins &amp; Users → Add admin → Restrict to local access only</i>, rol met beheerrechten voor Network, zonder 2FA). Met alleen een API-sleutel (<i>Settings → Control Plane → Integrations</i>) kan RzMon lezen maar niet weren.' => 'Create a <b>local account</b> for RzMon in UniFi (<i>Admins &amp; Users → Add admin → Restrict to local access only</i>, a role with admin rights for Network, without 2FA). With only an API key (<i>Settings → Control Plane → Integrations</i>) RzMon can read but not block.',
