    'Meldingen en ruis' => 'Alerts and noise',
    'Meldingen per dag (storingen en herstel)' => 'Alerts per day (incidents and recoveries)',
    'Per kanaal' => 'Per channel',
    'Daarnaast {i} info-meldingen, {d} IDS en {s} beveiliging.' => 'Plus {i} info alerts, {d} IDS and {s} security.',
    'Meeste meldingen' => 'Most alerts',
    'Snel weer goed (ruis)' => 'Quickly OK again (noise)',
    'binnen 5 min' => 'within 5 min',
    'Zet bij zulke checks "melden na N fouten" op 3: dan krijg je alleen nog een melding als het echt mis is.' => 'Set "alert after N failures" to 3 for such checks: then you only get an alert when something is really wrong.',
    'Geen checks die steeds binnen 5 minuten herstelden.' => 'No checks that kept recovering within 5 minutes.',
    'waakhond' => 'watchdog',
    'Zoeken en doen (Ctrl+K)' => 'Search and act (Ctrl+K)',
    'Zoeken' => 'Search',
    'Live: wijzigingen komen binnen een paar seconden binnen' => 'Live: changes arrive within a few seconds',
    '🔗 <b>Ook over servers heen bundelen</b>, met de waarschijnlijke oorzaak' => '🔗 <b>Also bundle across servers</b>, with the likely cause',
    'Gaan er binnen het bundelvenster meerdere servers mis, dan komt er één bericht, bv. "🔴 CRITICAL: 5 servers tegelijk · waarschijnlijk: ze hangen allemaal aan Switch-zolder (UniFi)". RzMon kijkt naar je afhankelijkheden, naar UniFi (welk access point of welke switch), naar agents die allemaal tegelijk stil zijn en naar je Proxmox-clusters.' => 'If several servers fail within the bundling window, you get one message, e.g. "🔴 CRITICAL: 5 servers at once · likely: they are all connected to Switch-attic (UniFi)". RzMon looks at your dependencies, at UniFi (which access point or switch), at agents that all go silent at once and at your Proxmox clusters.',
    'Slimme drempels' => 'Smart thresholds',
    'RzMon leert per check wat normaal is, per uur van de week (maandag 3:00 is anders dan dinsdag 14:00), en zet daar de drempels op. Na 7 dagen gegevens; daarna stelt hij ze elke nacht bij, hooguit 10% per nacht. Elke aanpassing staat in het <i>Wijzigingslogboek</i> en is terug te draaien. Werkt bij ping, TCP, HTTP, CPU, RAM en SNMP (CPU, geheugen, interface, load, temperatuur, UPS, UniFi); disks houden vaste drempels met de voorspelling.' => 'RzMon learns per check what is normal, per hour of the week (Monday 3:00 differs from Tuesday 14:00), and sets the thresholds accordingly. After 7 days of data; after that it adjusts them every night, at most 10% per night. Every adjustment is in the <i>Change log</i> and can be undone. Works for ping, TCP, HTTP, CPU, RAM and SNMP (CPU, memory, interface, load, temperature, UPS, UniFi); disks keep fixed thresholds with the forecast.',
    'Nieuwe checks' => 'New checks',
    'Slim met vangnet' => 'Smart with safety net',
    'Slim' => 'Smart',
    'Handmatig' => 'Manual',
    'Gevoeligheid' => 'Sensitivity',
    'rustig' => 'calm',
    'scherp' => 'sharp',
    '<b>Slim met vangnet</b>: geleerd, maar vanaf een harde grens altijd CRITICAL (bv. RAM 98%). <b>Rustig</b> geeft minder meldingen, <b>scherp</b> ziet een afwijking eerder. Per check aan te passen (✎). Stijgt de normaalwaarde van een check sluipend (een lek?), dan krijg je een ℹ️-melding en schuiven de drempels niet mee omhoog.' => '<b>Smart with safety net</b>: learned, but always CRITICAL from a hard limit (e.g. RAM 98%). <b>Calm</b> gives fewer alerts, <b>sharp</b> notices a deviation sooner. Adjustable per check (✎). If the normal value of a check creeps up (a leak?), you get an ℹ️ alert and the thresholds do not move up with it.',
    'Voorstel voor bestaande checks' => 'Proposal for existing checks',
    'Bestaande checks blijven handmatig tot je ze omzet. RzMon leert ook voor die checks, en laat hier zien waar slimme drempels minder warnings hadden gegeven.' => 'Existing checks stay manual until you switch them. RzMon also learns for those checks, and shows here where smart thresholds would have given fewer warnings.',
    'Statuspagina' => 'Status page',
    'Een eenvoudige pagina voor huisgenoten of klanten: de onderdelen die je hieronder kiest, of ze nu werken, en een balk per dag over de laatste 90 dagen. Geen IP-adressen, servernamen of foutteksten. Te openen via een <b>geheime link</b>, ook van buiten (met <i>Onzichtbaar van buiten</i> aan geeft een verkeerde link gewoon een 404).' => 'A simple page for housemates or customers: the components you choose below, whether they work right now, and a bar per day over the last 90 days. No IP addresses, server names or error texts. Opened via a <b>secret link</b>, also from outside (with <i>Invisible from outside</i> on, a wrong link simply gives a 404).',
    'Zoeken en doen' => 'Search and act',
    'Server, check, IP-adres of instelling… (bv. "rl02 disk onderhoud")' => 'Server, check, IP address or setting… (e.g. "rl02 disk maintenance")',
    '↑↓ kiezen · Enter doen · Esc sluiten · woorden als "onderhoud", "nu", "bevestig", "grafiek", "blokkeer" geven acties' => '↑↓ choose · Enter act · Esc close · words like "maintenance", "now", "ack", "graph", "block" give actions',
    'Werkt' => 'Operational',
    'Verstoord' => 'Degraded',
    'Alles werkt' => 'All systems operational',
    'Gedeeltelijk verstoord' => 'Partially degraded',
    'Er is een storing' => 'There is an outage',
    'Status onbekend' => 'Status unknown',
    'Beschikbaarheid per dag, laatste {n} dagen' => 'Availability per day, last {n} days',
    'geen gegevens' => 'no data',
    'beschikbaar' => 'available',
    'Er zijn nog geen onderdelen ingesteld.' => 'No components have been set up yet.',
    '{n} check(s) zouden met slimme drempels minder warnings geven (bv. {c} op {h}: {a} → {b} dagen)' => '{n} check(s) would give fewer warnings with smart thresholds (e.g. {c} on {h}: {a} → {b} days)',
    'ze hangen allemaal achter {p}: kijk daar eerst' => 'they all depend on {p}: look there first',
    'ze hangen allemaal aan {d} (UniFi): ligt die eruit?' => 'they are all connected to {d} (UniFi): is it down?',
    'alle agents zijn tegelijk stil ({s} van {a}): ligt het aan RzMon zelf of aan zijn netwerkverbinding?' => 'all agents went silent at once ({s} of {a}): is it RzMon itself or its network connection?',
    'ze zitten allemaal in Proxmox-cluster {c}' => 'they are all in Proxmox cluster {c}',
    '{n} servers tegelijk' => '{n} servers at once',
    'waarschijnlijk: {c}' => 'likely: {c}',
    'Zelf hersteld' => 'Self-healed',
    'Zelf herstellen mislukt' => 'Self-healing failed',
    '{h} was zelf offline: kon RzMon en Pushover {m} min niet bereiken (vanaf {t})' => '{h} was offline itself: could not reach RzMon and Pushover for {m} min (from {t})',
    '{h} kon RzMon {m} min niet bereiken (vanaf {t}){s}' => '{h} could not reach RzMon for {m} min (from {t}){s}',
    'de waakhond heeft het via Pushover gemeld' => 'the watchdog reported it via Pushover',
    'normaal op dit uur {lo}–{hi}{u}' => 'normal at this hour {lo}–{hi}{u}',
    '🧠 {c}: de normaalwaarde stijgt, van {a}{u} naar {b}{u} in twee weken. Een lek of groeiende belasting? RzMon past de drempels hier niet zomaar op aan.' => '🧠 {c}: the normal value is rising, from {a}{u} to {b}{u} in two weeks. A leak or growing load? RzMon does not simply raise the thresholds for this.',
    '🧠 Slimme drempels actief: {c} op {h}' => '🧠 Smart thresholds active: {c} on {h}',
    '🧠 Slimme drempels bijgesteld: {c} op {h}' => '🧠 Smart thresholds adjusted: {c} on {h}',
    'Vorige slimme drempels teruggezet; RzMon leert vannacht verder (zet de check op Handmatig om dat te stoppen)' => 'Previous smart thresholds restored; RzMon continues learning tonight (set the check to Manual to stop that)',
    'Onbekende modus' => 'Unknown mode',
    'drempelmodus' => 'threshold mode',
    'Vaste drempels' => 'Fixed thresholds',
    'niet in gebruik: slimme drempels' => 'not in use: smart thresholds',
    'in gebruik tot RzMon genoeg geleerd heeft' => 'in use until RzMon has learned enough',
    'Deze check gebruikt nu slimme drempels met vangnet' => 'This check now uses smart thresholds with a safety net',
    'leert nog ({d}/{n} dagen); tot die tijd gelden de vaste drempels' => 'still learning ({d}/{n} days); until then the fixed thresholds apply',
    'Nu ({d} {h}:00): normaal {lo}–{hi}{u}' => 'Now ({d} {h}:00): normal {lo}–{hi}{u}',
    'slim zou zijn: warning vanaf {w}{u}, critical vanaf {c}{u}' => 'smart would be: warning from {w}{u}, critical from {c}{u}',
    'warning vanaf {w}{u}, critical vanaf {c}{u}' => 'warning from {w}{u}, critical from {c}{u}',
    'altijd critical vanaf {g}{u}' => 'always critical from {g}{u}',
    'Afgelopen {d} dagen: met vaste drempels op {f} dag(en) een warning, met slimme drempels op {s}.' => 'Last {d} days: with fixed thresholds a warning on {f} day(s), with smart thresholds on {s}.',
    'De normaalwaarde stijgt: van {a}{u} naar {b}{u} in twee weken. Zolang dat zo is, schuiven de drempels niet mee omhoog.' => 'The normal value is rising: from {a}{u} to {b}{u} in two weeks. As long as that lasts, the thresholds do not move up with it.',
    'warning' => 'warning',
    'Normaal per uur van de week' => 'Normal per hour of the week',
    'Grijs: normaal (10e–95e percentiel) per uur van de week. Lijn: warning. Streep: nu.' => 'Grey: normal (10th–95th percentile) per hour of the week. Line: warning. Dash: now.',
    'Nog geen voorstellen: RzMon heeft per check minstens 7 dagen meetwaarden nodig, of al je checks die kunnen leren staan al op slim.' => 'No proposals yet: RzMon needs at least 7 days of measurements per check, or all your checks that can learn are already smart.',
    'Dagen met een warning in de laatste weken' => 'Days with a warning in recent weeks',
    'Vast' => 'Fixed',
    '{n} van {d} dagen' => '{n} of {d} days',
    'Gekozen checks: slim met vangnet' => 'Selected checks: smart with safety net',
    '{n} check(s) omgezet' => '{n} check(s) switched',
    '{n} check(s): {list}' => '{n} check(s): {list}',
    'kies checks' => 'choose checks',
    'bv. Internet, NAS, Plex' => 'e.g. Internet, NAS, Plex',
    'Statuspagina aan' => 'Status page on',
    'Titel' => 'Title',
    'Mededeling' => 'Announcement',
    '(optioneel, bv. "Zaterdag 9:00–10:00 onderhoud aan de NAS")' => '(optional, e.g. "Saturday 9:00–10:00 maintenance on the NAS")',
    'Onderdelen' => 'Components',
    'Per onderdeel een naam en de checks die erbij horen (klik om ze aan te vinken). Het ergste van die checks telt; checks in onderhoud tonen "Onderhoud".' => 'Per component a name and the checks that belong to it (click to tick them). The worst of those checks counts; checks in maintenance show "Maintenance".',
    'Geheime link' => 'Secret link',
    'Tip: vul bij Instellingen → Systeem het adres van RzMon in (base_url) als RzMon van buiten anders heet. ' => 'Tip: enter the address of RzMon under Settings → System (base_url) if RzMon has a different name from outside. ',
    'Een nieuwe link maken? Dan werkt de oude meteen niet meer.' => 'Make a new link? Then the old one stops working immediately.',
    'Nieuwe link' => 'New link',
    'Openen' => 'Open',
    'Nieuwe link maken? De oude link werkt dan meteen niet meer.' => 'Make a new link? The old link will stop working immediately.',
    'Tijdlijn van {ip}' => 'Timeline of {ip}',
    'IDS, logins en blokkades van dit adres' => 'IDS, logins and blocks of this address',
    'op al je servers' => 'on all your servers',
    'Onderhoud: {n}' => 'Maintenance: {n}',
    'hele server' => 'whole server',
    'Agent Manager: {n}' => 'Agent Manager: {n}',
    'Server bewerken: {n}' => 'Edit server: {n}',
    'Nu checken: {c}' => 'Check now: {c}',
    '{c} gecheckt' => '{c} checked',
    'Onderhoud: {c}' => 'Maintenance: {c}',
    'Bevestigen: {c}' => 'Acknowledge: {c}',
    'Grafiek: {c}' => 'Graph: {c}',
    'Check bewerken: {c}' => 'Edit check: {c}',
    'tabblad' => 'tab',
    'Onderhoud: alles' => 'Maintenance: everything',
    'alle meldingen pauzeren' => 'pause all alerts',
    'Altijd critical vanaf' => 'Always critical from',
    'standaard ({s})' => 'default ({s})',
    'Zelf herstellen' => 'Self-healing',
    'herstarten (service of container)' => 'restart (service or container)',
    'herstelcommando {n}' => 'repair command {n}',
    'Draait de {w} niet, dan herstart de agent hem zelf, vóór zijn rapport. Lukt dat, dan krijg je alleen een ℹ️-melding; lukt het niet, de gewone melding. Hooguit één poging per 10 minuten en 3 per dag.' => 'If the {w} is not running, the agent restarts it itself, before its report. If that works, you only get an ℹ️ alert; if not, the normal alert. At most one attempt per 10 minutes and 3 per day.',
    'service' => 'service',
    'Gaat deze check mis, dan voert de agent het herstelcommando uit (alleen via een versleutelde verbinding) en meldt RzMon pas als dat niet helpt, of na 5 minuten. Het commando zelf staat alleen op de server, in <code>/etc/rzmon-agent/heal.d/</code>.' => 'If this check fails, the agent runs the repair command (only over an encrypted connection) and RzMon only alerts if that does not help, or after 5 minutes. The command itself lives only on the server, in <code>/etc/rzmon-agent/heal.d/</code>.',
    'Eigen herstelcommando\'s zet je op de server in <code>/etc/rzmon-agent/heal.d/</code> (uitvoerbaar, van root, niet door anderen te wijzigen); daarna staan ze hier.' => 'Put your own repair commands on the server in <code>/etc/rzmon-agent/heal.d/</code> (executable, owned by root, not writable by others); after that they appear here.',
    'De drempels hierboven gelden altijd.' => 'The thresholds above always apply.',
    'RzMon leert {n} dagen wat normaal is, per uur van de week; tot die tijd gelden de drempels hierboven. Daarna stelt hij ze elke nacht bij (hooguit 10% per nacht). Elke aanpassing staat in het wijzigingslogboek, terug te draaien.' => 'RzMon learns for {n} days what is normal, per hour of the week; until then the thresholds above apply. After that it adjusts them every night (at most 10% per night). Every adjustment is in the change log and can be undone.',
    'Vanaf het vangnet is het altijd CRITICAL, wat RzMon ook geleerd heeft.' => 'From the safety net it is always CRITICAL, whatever RzMon has learned.',
    'Waakhond:' => 'Watchdog:',
    'melden na' => 'alert after',
    'min' => 'min',
    'deze agent stuurt zelf een Pushover-bericht als RzMon onbereikbaar is of de checks stilstaan' => 'this agent sends a Pushover message itself if RzMon is unreachable or the checks have stopped',
    'Waakhond aan voor {name}; de agent pakt het binnen een paar minuten op' => 'Watchdog on for {name}; the agent picks it up within a few minutes',
    'Waakhond uit voor {name}' => 'Watchdog off for {name}',
    'Zet eerst Pushover aan (Meldingen → Kanalen): de waakhond meldt via Pushover' => 'Turn on Pushover first (Alerts → Channels): the watchdog reports via Pushover',
    'Werkt alleen versleuteld: koppel de agent met een koppelcode (de Pushover-gegevens gaan naar de agent)' => 'Only works encrypted: pair the agent with a pairing code (the Pushover details are sent to the agent)',
    'actief: na {n} min zonder RzMon een Pushover-bericht, en een bericht als de checks stilstaan' => 'active: a Pushover message after {n} min without RzMon, and a message if the checks have stopped',
    'Normaalwaarde stijgt sluipend (slimme drempels)' => 'Normal value creeping up (smart thresholds)',
    'Zelf hersteld (of herstel mislukt)' => 'Self-healed (or healing failed)',
    'Waakhond: RzMon was onbereikbaar of de checks stonden stil' => 'Watchdog: RzMon was unreachable or the checks had stopped',
    'standaard' => 'default',
    'Alleen voor checks die kunnen leren (ping, TCP, HTTP, CPU, RAM, SNMP); de andere blijven zoals ze zijn. Bij slim met vangnet krijgt een check zonder vangnet het standaard vangnet.' => 'Only for checks that can learn (ping, TCP, HTTP, CPU, RAM, SNMP); the others stay as they are. With smart with safety net, a check without a safety net gets the default safety net.',
    'geleerd' => 'learned',
    'Escaleren' => 'Escalation',
    '<b>Escaleren</b>: een storing die niemand bevestigt, na een tijd nog een keer melden, een stap hoger' => '<b>Escalate</b>: an outage nobody acknowledges is notified again after a while, one step higher',
    'Warning: na … min' => 'Warning: after … min',
    '(0 = nooit)' => '(0 = never)',
    'Critical: na … min' => 'Critical: after … min',
    'Critical wordt' => 'Critical becomes',
    'hoge prioriteit' => 'high priority',
    'nood (herhaalt tot je bevestigt)' => 'emergency (repeats until you acknowledge)',
    'Niet escaleren tijdens de stille uren' => 'Don\'t escalate during quiet hours',
    'Een warning gaat dan als critical (de prioriteit van je critical-meldingen), een critical krijgt de prioriteit hierboven. Eén keer per storing; bevestigen stopt het.' => 'A warning is then sent as critical (the priority of your critical alerts), a critical gets the priority above. Once per outage; acknowledging stops it.',
    'Slim: overige instellingen' => 'Smart: other settings',
    'Slim interval' => 'Smart interval',
    '<b>Slim interval</b>: bij een probleem sneller checken, als alles al een uur goed is trager' => '<b>Smart interval</b>: check faster when there is a problem, slower when everything has been fine for an hour',
    'Bij een probleem elke … seconden' => 'During a problem every … seconds',
    '(ping, TCP, HTTP, SNMP)' => '(ping, TCP, HTTP, SNMP)',
    'Stabiel: hooguit … × het interval' => 'Stable: at most … × the interval',
    '(nooit trager dan een uur)' => '(never slower than an hour)',
    'Sneller checken laat je eerder weten of een storing echt is (en wanneer hij voorbij is); trager checken ontlast je servers als alles goed gaat. Checks van de agent volgen het rapport van de agent.' => 'Checking faster tells you sooner whether an outage is real (and when it is over); checking slower takes load off your servers when all is well. Agent checks follow the agent\'s report.',
    'Afwijkingen en hints' => 'Anomalies and hints',
    '<b>Afwijkingen</b> bij checks zonder drempels (verkeer, clients, processen, logregels): ℹ️ als het flink anders is dan normaal op dat uur' => '<b>Anomalies</b> for checks without thresholds (traffic, clients, processes, log lines): ℹ️ when it is very different from normal for that hour',
    '<b>Disk groeit hard</b>: ℹ️ als een disk in een uur zoveel procentpunt groeit:' => '<b>Disk grows fast</b>: ℹ️ when a disk grows this many percentage points in an hour:',
    '<b>Oorzaak erbij</b>: in de melding wat er vlak ervoor gebeurde (update, herstart, wijziging)' => '<b>Add the cause</b>: what happened just before, in the alert (update, restart, change)',
    '<b>Heartbeats leren hun ritme</b>: warning als hij later is dan normaal, of de meegestuurde waarde veel kleiner of groter' => '<b>Heartbeats learn their rhythm</b>: warning when one is later than usual, or the value sent is much smaller or larger',
    'Afwijkingen en "disk groeit hard" staan bij Meldingen → Systeeminfo; standaard alleen op de meldingenpagina.' => 'Anomalies and "disk grows fast" are under Alerts → System info; by default only on the alerts page.',
    'Slimme voorstellen' => 'Smart suggestions',
    'Nu opnieuw bepalen (anders elke nacht)' => 'Recalculate now (otherwise every night)',
    'Elke nacht kijkt RzMon naar de geschiedenis en stelt voor: melden na meer (of minder) mislukte checks, een vast onderhoudsvenster voor iets dat steeds op hetzelfde moment gebeurt, en afhankelijkheden (volgens UniFi, of omdat servers steeds samen uitvallen). Niets verandert tot jij op Toepassen klikt; een genegeerd voorstel komt niet terug. Alles staat in het wijzigingslogboek.' => 'Every night RzMon looks at the history and suggests: alert after more (or fewer) failed checks, a fixed maintenance window for something that keeps happening at the same time, and dependencies (from UniFi, or because servers keep failing together). Nothing changes until you click Apply; a dismissed suggestion does not come back. Everything is in the change log.',
    'Vaste onderhoudsvensters' => 'Fixed maintenance windows',
    'Elke dag of op één weekdag een tijd zonder meldingen, voor een server of één check (bv. de back-up om 2:00 of de herstart op zondag).' => 'Every day or on one weekday a time without alerts, for a server or a single check (e.g. the backup at 2:00 or the restart on Sunday).',
    'vast onderhoudsvenster' => 'fixed maintenance window',
    'Kies een server of check en een begintijd (uu:mm)' => 'Choose a server or check and a start time (hh:mm)',
    'Vast onderhoudsvenster: {w}' => 'Fixed maintenance window: {w}',
    'Vast onderhoudsvenster weg: {w}' => 'Fixed maintenance window removed: {w}',
    '{l}: {d} {s} ({m} min)' => '{l}: {d} {s} ({m} min)',
    'Melden na {n} mislukte checks (nu {c}): {s} van de {e} storingen waren binnen 5 minuten vanzelf weer goed' => 'Alert after {n} failed checks (now {c}): {s} of the {e} outages recovered by themselves within 5 minutes',
    'Meteen melden (nu na {c}): de laatste {e} storingen duurden allemaal lang' => 'Alert immediately (now after {c}): the last {e} outages all lasted long',
    'Vast onderhoudsvenster {d} {s} ({m} min): {n}× op dat moment een storing die vanzelf herstelde' => 'Fixed maintenance window {d} {s} ({m} min): {n}× an outage at that time that recovered by itself',
    'Hangt af van {p}: hangt er volgens UniFi aan' => 'Depends on {p}: connected to it according to UniFi',
    'Hangt af van {p}: viel {n} van de {o} keer tegelijk uit' => 'Depends on {p}: went down at the same time {n} of {o} times',
    'Dit voorstel bestaat niet (meer)' => 'This suggestion does not exist (anymore)',
    'Genegeerd; dit voorstel komt niet terug' => 'Dismissed; this suggestion won\'t come back',
    'voorstel' => 'suggestion',
    'Melden na {n} mislukte checks' => 'Alert after {n} failed checks',
    'patroon herkend door RzMon' => 'pattern recognised by RzMon',
    'Vast onderhoudsvenster toegevoegd' => 'Fixed maintenance window added',
    'Afhankelijkheid ingesteld' => 'Dependency set',
    '{n} slimme voorstel(len) om te bekijken (melden na N, vaste onderhoudsvensters, afhankelijkheden)' => '{n} smart suggestion(s) to review (alert after N, fixed maintenance windows, dependencies)',
    'gewijzigd in RzMon: {l}' => 'changed in RzMon: {l}',
    '{m} min eerder: {w}' => '{m} min before: {w}',
    'Kort ervoor' => 'Just before',
    'vandaag nog niet binnen: meestal rond {t}' => 'not received yet today: usually around {t}',
    'veel minder dan normaal ({v}, meestal {m})' => 'much less than normal ({v}, usually {m})',
    'veel meer dan normaal ({v}, meestal {m})' => 'much more than normal ({v}, usually {m})',
    'ESCALATIE' => 'ESCALATION',
    'Al {m} min {s} en niet bevestigd.' => '{s} for {m} min and not acknowledged.',
    'Groeit hard: +{j} procentpunt in een uur (nu {n}%). Een log of download die uit de hand loopt?' => 'Growing fast: +{j} percentage points in an hour (now {n}%). A log or download getting out of hand?',
    'nog niet bevestigd, {status}' => 'not acknowledged yet, {status}',
    'Ongebruikelijk hoog: {v}' => 'Unusually high: {v}',
    'Ongebruikelijk laag: {v}' => 'Unusually low: {v}',
    'normaal op dit uur {lo}–{hi}' => 'normal for this hour {lo}–{hi}',
    '{n} nieuwe voorstel(len)' => '{n} new suggestion(s)',
    'Melden na N mislukte checks' => 'Alert after N failed checks',
    'Vast onderhoudsvenster' => 'Fixed maintenance window',
    'Afhankelijkheid' => 'Dependency',
    'Toepassen' => 'Apply',
    'Geen open voorstellen.' => 'No open suggestions.',
    'Laatst bekeken: {d}.' => 'Last reviewed: {d}.',
    'De eerste keer vannacht (of nu met 🔄).' => 'The first time tonight (or now with 🔄).',
    'Voor' => 'For',
    'Nog geen vaste onderhoudsvensters.' => 'No fixed maintenance windows yet.',
    'Venster toevoegen' => 'Add window',
    'Vanaf' => 'From',
    'Minuten' => 'Minutes',
    'Weggehaald' => 'Removed',
    'Bestaande checks blijven handmatig tot je ze omzet. RzMon leert ook voor die checks en rekent na: <b>op hoeveel van de afgelopen dagen was er een warning geweest</b>, met de drempels van nu en met slimme drempels. Een dag telt net als een echte melding: pas als er zoveel metingen <b>achter elkaar</b> te hoog waren als de check vraagt (<i>melden na N</i>).' => 'Existing checks stay manual until you switch them. RzMon also learns for those checks and works out: <b>on how many of the past days would there have been a warning</b>, with the current thresholds and with smart thresholds. A day counts just like a real alert: only when as many measurements <b>in a row</b> were too high as the check asks for (<i>alert after N</i>).',
    '<b>Minder dagen met slim</b> = minder onnodige meldingen: die checks staan al aangevinkt. <b>Grijs</b> = slim levert daar niets op; de reden staat erachter. <b>Grillig</b> = de check piekt bijna elke dag even (bv. de webinterface van een camera); daar helpt <i>melden na 3</i> meer dan slimme drempels.' => '<b>Fewer days with smart</b> = fewer needless alerts: those checks are already ticked. <b>Grey</b> = smart gains nothing there; the reason is shown next to it. <b>Spiky</b> = the check briefly peaks almost every day (e.g. a camera\'s web interface); <i>alert after 3</i> helps more there than smart thresholds.',
    'Geteld zoals een melding: {n} metingen achter elkaar te hoog.' => 'Counted like an alert: {n} measurements in a row too high.',
    'Deze check piekt bijna elke dag even. Met melden na {n} wordt dat geen melding: dat is goed zo.' => 'This check briefly peaks almost every day. With alert after {n} that doesn\'t become an alert: that\'s fine.',
    'Deze check piekt bijna elke dag even, maar dat houdt meestal niet aan. Slimme drempels helpen daar weinig; zet hem op melden na 3 (✎ → 🔔 Meldingen → Melden na … mislukte checks).' => 'This check briefly peaks almost every day, but it usually doesn\'t last. Smart thresholds help little there; set it to alert after 3 (✎ → 🔔 Alerts → Alert after … failed checks).',
    'Gaat het je om de bereikbaarheid, dan is een ping-check betrouwbaarder dan de responstijd.' => 'If you care about reachability, a ping check is more reliable than the response time.',
    'nu zonder drempel: met slim wordt hij bewaakt' => 'no threshold now: with smart it gets monitored',
    '{n} dag(en) minder met een warning' => '{n} fewer day(s) with a warning',
    'slim is strenger: {n} dag(en) meer met een warning' => 'smart is stricter: {n} more day(s) with a warning',
    'geen verschil: met allebei rustig' => 'no difference: quiet with both',
    'geen winst: met slim even vaak een warning' => 'no gain: just as many warnings with smart',
    'grillig: piekt bijna elke dag even (tip: melden na 3)' => 'spiky: briefly peaks almost every day (tip: alert after 3)',
    'grillig: piekt bijna elke dag even' => 'spiky: briefly peaks almost every day',
    'wordt vannacht opnieuw berekend' => 'recalculated tonight',
    'Dagen met een warning, met de drempels die nu gelden' => 'Days with a warning, with the thresholds that apply now',
    'Dagen met warning – nu' => 'Days with warning – now',
    'Dagen met een warning als de check slimme drempels had gehad' => 'Days with a warning if the check had had smart thresholds',
    '– met slim' => '– with smart',
    'Waarom' => 'Why',
    '<i>Melden na N</i> blijft gelijk: bij een check op <i>melden na 3</i> en een interval van 1 minuut gaat de melding pas uit als het <b>2 minuten</b> mis is, net als zonder slim interval. Het snellere checken maakt een korte hapering dus niet alsnog tot een melding; wel weet RzMon sneller dat het weer goed is.' => '<i>Alert after N</i> stays the same: for a check on <i>alert after 3</i> with a 1-minute interval, the alert only goes out once it has been failing for <b>2 minutes</b>, just like without smart interval. Faster checking therefore doesn\'t turn a brief hiccup into an alert after all; RzMon does see sooner that it\'s fine again.',
    '{n} nieuwe problemen' => '{n} new problems',
    'Onbekende regel' => 'Unknown rule',
    '🛰️ Live' => '🛰️ Live',
    '🔏 Regels' => '🔏 Rules',
    'Alleen treffers' => 'Hits only',
    'Zoeken: naam, techniek (T1059) …' => 'Search: name, technique (T1059) …',
    'Endpoint-bewaking' => 'Endpoint monitoring',
    'De agent (1.63.0) kijkt op het moment zelf mee: nieuwe <b>processen</b> (auditd), <b>verbindingen</b> en luisterpoorten, nieuwe <b>bestanden</b> in tijdelijke mappen en webmappen (inotify) en <b>containers</b>. RzMon toetst alles aan zijn eigen regels en aan de open <b>Sigma</b>-regels; een treffer wordt een incident, met het bewijs erbij. Alles staat ook op <i>🛡️ IDS → 🛰️ Live</i>. Per server aan/uit in de Agent Manager.' => 'The agent (1.63.0) watches as it happens: new <b>processes</b> (auditd), <b>connections</b> and listening ports, new <b>files</b> in temporary and web folders (inotify) and <b>containers</b>. RzMon checks everything against its own rules and the open <b>Sigma</b> rules; a hit becomes an incident, with the evidence attached. Everything is also on <i>🛡️ IDS → 🛰️ Live</i>. On/off per server in the Agent Manager.',
    '<b>Endpoint-bewaking aan</b> (op de servers waar het in de Agent Manager aan staat)' => '<b>Endpoint monitoring on</b> (on the servers where it is on in the Agent Manager)',
    '<b>Sigma-regels</b> van SigmaHQ gebruiken (naast de eigen regels van RzMon)' => 'Use the <b>Sigma rules</b> from SigmaHQ (alongside RzMon\'s own rules)',
    '<b>Payload-inspectie</b> van verdachte webverzoeken (SWAG): SQL-injectie, XSS, Log4Shell, bekende exploits met CVE …' => '<b>Payload inspection</b> of suspicious web requests (SWAG): SQL injection, XSS, Log4Shell, known exploits with CVE …',
    'Zelf ingrijpen (alleen in de modus ⛔ Blokkeren)' => 'Step in automatically (only in ⛔ Block mode)',
    '<b>Proces stoppen</b> bij een regel die dat zegt (webshell, reverse shell, cryptominer …)' => '<b>Stop the process</b> for a rule that says so (webshell, reverse shell, cryptominer …)',
    '<b>IP blokkeren</b> bij een webaanval met een herkende payload' => '<b>Block the IP</b> on a web attack with a recognised payload',
    '<b>Server isoleren</b> (24 uur) bij een reverse shell of cryptominer: alleen RzMon en je LAN kunnen er dan nog bij' => '<b>Isolate the server</b> (24 hours) on a reverse shell or cryptominer: only RzMon and your LAN can still reach it',
    'Wat RzMon zelf doet, staat altijd in het incident en gaat als critical ook naar Pushover. In de modus 🎓 Leren grijpt RzMon nooit in, maar meldt het wel.' => 'Whatever RzMon does by itself is always in the incident and, as critical, also goes to Pushover. In 🎓 Learn mode RzMon never steps in, but does report it.',
    'proces {pid} wordt gestopt' => 'process {pid} is being stopped',
    'Endpoint: {r}' => 'Endpoint: {r}',
    'server geïsoleerd (24 uur)' => 'server isolated (24 hours)',
    'modus Leren: RzMon greep niet in' => 'Learn mode: RzMon did not step in',
    'Sigma-regel van {a} (SigmaHQ, DRL 1.1)' => 'Sigma rule by {a} (SigmaHQ, DRL 1.1)',
    'ouder' => 'parent',
    'naar' => 'to',
    'luistert op poort {p}' => 'listens on port {p}',
    'bevat {w}' => 'contains {w}',
    'Onbekend onderdeel' => 'Unknown component',
    'Ernstig: dit gedrag past bij een inbraak. Ga uit van een hack tot je zeker weet dat jij of een bekend programma dit deed.' => 'Serious: this behaviour fits a break-in. Assume a hack until you are sure you or a known program did this.',
    'Verdacht, maar vaak ook gewoon onderhoud. Kijk naar het programma, de ouder en de gebruiker bij het bewijs hieronder.' => 'Suspicious, but often just maintenance. Look at the program, the parent and the user in the evidence below.',
    'Was jij dit, of een programma dat je kent? Klik "Ja, dit was ik": dan wordt het voor deze server niet meer gemeld.' => 'Was this you, or a program you know? Click "Yes, this was me": then it is no longer reported for this server.',
    'Niet: laat het proces stoppen, isoleer de server en zoek uit hoe het binnenkwam.' => 'If not: stop the process, isolate the server and find out how it got in.',
    'Processen als boom, met hun verbindingen' => 'Processes as a tree, with their connections',
    'Wat er net gebeurde (auditd)' => 'What just happened (auditd)',
    'Houd alles bijgewerkt, laat diensten niet als root draaien, en zet /tmp en /dev/shm op noexec.' => 'Keep everything updated, don\'t run services as root, and mount /tmp and /dev/shm noexec.',
    'Vanaf {ip} kwamen verzoeken met een aanval erin (zie het bewijs hieronder: de techniek, het verdachte stuk en, als het bekend is, de CVE).' => 'Requests containing an attack came from {ip} (see the evidence below: the technique, the suspicious part and, if known, the CVE).',
    'Meestal een geautomatiseerde scanner die het hele internet afgaat. Ernstig als een verzoek een gewoon antwoord (2xx) kreeg en jouw software kwetsbaar is voor die CVE.' => 'Usually an automated scanner sweeping the whole internet. Serious if a request got a normal answer (2xx) and your software is vulnerable to that CVE.',
    'Blokkeer het IP-adres (gebeurt vanzelf in de modus Blokkeren).' => 'Block the IP address (happens automatically in Block mode).',
    'Staat er een CVE bij: controleer of je die software gebruikt en bijgewerkt hebt (tabblad Kwetsbaarheden).' => 'If there is a CVE: check whether you use that software and have updated it (Vulnerabilities tab).',
    'Houd websites en diensten achter SWAG bijgewerkt; zet alleen open wat echt van buiten bereikbaar moet zijn.' => 'Keep websites and services behind SWAG updated; only expose what really has to be reachable from outside.',
    'scanner {ua}' => 'scanner {ua}',
    '{n} verdachte verzoek(en)' => '{n} suspicious request(s)',
    '{n} kreeg een gewoon antwoord (2xx/3xx): kijk of het lukte' => '{n} got a normal answer (2xx/3xx): check whether it worked',
    'Webaanval: {what}' => 'Web attack: {what}',
    'Webaanval vanaf {ip}: {what}' => 'Web attack from {ip}: {what}',
    'Geïnstalleerd: {p}' => 'Installed: {p}',
    'Installeren mislukt: {p}' => 'Installation failed: {p}',
    'Regel aan' => 'Rule on',
    'Regel uit' => 'Rule off',
    'nieuwe processen, kernelmodules en bewaakte paden' => 'new processes, kernel modules and watched paths',
    'nieuwe bestanden in tijdelijke mappen en webmappen' => 'new files in temporary and web folders',
    'auditd draait niet' => 'auditd is not running',
    'Endpoint-bewaking: klik om het via de agent te installeren' => 'Endpoint monitoring: click to install it via the agent',
    'ontbreekt: {what}' => 'missing: {what}',
    'installeren?' => 'install?',
    'Endpoint-bewaking:' => 'Endpoint monitoring:',
    'processen, netwerk, bestanden en containers meteen bekeken; RzMon grijpt in bij een aanval' => 'processes, network, files and containers watched as it happens; RzMon steps in on an attack',
    'Endpoint-bewaking aan voor {name}; de agent pakt het binnen een minuut op' => 'Endpoint monitoring on for {name}; the agent picks it up within a minute',
    'Endpoint-bewaking uit voor {name}' => 'Endpoint monitoring off for {name}',
    'processen en bewaakte paden (auditd)' => 'processes and watched paths (auditd)',
    'auditd ontbreekt' => 'auditd is missing',
    'auditd is geïnstalleerd maar draait niet' => 'auditd is installed but not running',
    'auditd staat op slot (-e 2): regels pas na een herstart' => 'auditd is locked (-e 2): rules only after a reboot',
    'Werkt pas als het IDS aan staat (Instellingen → IDS).' => 'Only works when the IDS is on (Settings → IDS).',
    'Staat voor alle servers uit (Instellingen → IDS → Endpoint-bewaking).' => 'Off for all servers (Settings → IDS → Endpoint monitoring).',
    'Uit voor deze server.' => 'Off for this server.',
    'Nog geen gegevens van de agent (agent {v} of nieuwer nodig).' => 'No data from the agent yet (agent {v} or newer needed).',
    'bestanden (inotify)' => 'files (inotify)',
    'netwerk' => 'network',
    'containers ({rt})' => 'containers ({rt})',
    'geen containers' => 'no containers',
    'realtime-watcher actief' => 'realtime watcher active',
    'de realtime-watcher draait (nog) niet' => 'the realtime watcher is not running (yet)',
    'geen systemd: alleen bij de gewone runs' => 'no systemd: only during the regular runs',
    '{n} gebeurtenissen overgeslagen (te veel tegelijk)' => '{n} events skipped (too many at once)',
    'Wordt geïnstalleerd: {p}' => 'Being installed: {p}',
    'via de agent kan het hier niet: {why}' => 'not possible via the agent here: {why}',
    'Installeren via de agent' => 'Install via the agent',
    'of zelf:' => 'or yourself:',
    '{c} installeren op {name}? {how}' => 'Install {c} on {name}? {how}',
    'Typ INSTALLEREN om te bevestigen.' => 'Type INSTALL to confirm.',
    'Bevestig met je wachtwoord.' => 'Confirm with your password.',
    'De agent installeert {c} bij zijn volgende rapport' => 'The agent installs {c} with its next report',
    'accounts/sudo' => 'accounts/sudo',
    'cron/systemd/ssh' => 'cron/systemd/ssh',
    'kernelmodule' => 'kernel module',
    'Endpoint-bewaking staat uit (Instellingen → IDS → Endpoint-bewaking)' => 'Endpoint monitoring is off (Settings → IDS → Endpoint monitoring)',
    '{n} gebeurtenissen (laatste 3 dagen, hooguit 300)' => '{n} events (last 3 days, at most 300)',
    'Nog niets gezien. Staat de endpoint-bewaking aan op je servers (Agent Manager), en is de agent 1.63.0 of nieuwer?' => 'Nothing seen yet. Is endpoint monitoring on for your servers (Agent Manager), and is the agent 1.63.0 or newer?',
    'stopt het proces' => 'stops the process',
    'blokkeert het IP' => 'blocks the IP',
    'isoleert de server' => 'isolates the server',
    '{on} van {n} regels aan. Eigen regels van RzMon (met uitleg) en de Linux-regels van SigmaHQ (licentie DRL 1.1). Een regel uitzetten geldt voor alle servers; "Dit is normaal" bij een incident geldt voor één server.' => '{on} of {n} rules on. RzMon\'s own rules (with explanations) and the Linux rules from SigmaHQ (licence DRL 1.1). Turning a rule off applies to all servers; "This is normal" on an incident applies to one server.',
    'Sigma-regels staan uit (Instellingen → IDS → Endpoint-bewaking).' => 'Sigma rules are off (Settings → IDS → Endpoint monitoring).',
    'Regel' => 'Rule',
    'Doet zelf' => 'Acts by itself',
    'Treffers in de laatste 3 dagen' => 'Hits in the last 3 days',
    'Treffers' => 'Hits',
    'bron' => 'source',
    'Verzoek' => 'Request',
    'Gedecodeerd' => 'Decoded',
    'Gewoon antwoord: kijk of het lukte' => 'Normal answer: check whether it worked',
    'Geweigerd of niet gevonden' => 'Refused or not found',
    'Programma' => 'Program',
    'Opdracht' => 'Command',
    'Ouder' => 'Parent',
    'ingelogd als uid {n}' => 'logged in as uid {n}',
    'Map' => 'Folder',
    'Luistert op' => 'Listens on',
    'Naar' => 'To',
    'Bestand' => 'File',
    'ja (programma)' => 'yes (program)',
    'Verdachte code' => 'Suspicious code',
    'Actie' => 'Action',
    'RzMon deed' => 'RzMon did',
    'Sigma-regel van {a}' => 'Sigma rule by {a}',
    'kan ook: {fp}' => 'can also be: {fp}',
    'Inspectie' => 'Inspection',
    'IDS: endpoint-bewaking' => 'IDS: endpoint monitoring',
    'Webserver start een shell of netwerkprogramma' => 'Web server starts a shell or network program',
    'Een webserver (nginx, PHP, Java …) hoort geen shell, curl of netcat te starten. Meestal is via een lek in een website een opdracht uitgevoerd (webshell).' => 'A web server (nginx, PHP, Java …) should not start a shell, curl or netcat. Usually a command was run through a hole in a website (webshell).',
    'Reverse shell' => 'Reverse shell',
    'Een opdracht die een shell naar buiten opent, zodat iemand van buiten op deze server kan typen (bash -i >& /dev/tcp/…, nc -e, socat exec, python/perl/php met een socket).' => 'A command that opens a shell to the outside, so someone outside can type on this server (bash -i >& /dev/tcp/…, nc -e, socat exec, python/perl/php with a socket).',
    'Downloaden en meteen uitvoeren' => 'Download and run immediately',
    'Iets van internet halen en direct laten draaien (curl … | sh, wget -O- | bash, base64 -d | sh). Zo zetten aanvallers hun eigen programma op een server.' => 'Fetching something from the internet and running it straight away (curl … | sh, wget -O- | bash, base64 -d | sh). That is how attackers put their own program on a server.',
    'Programma gestart vanuit /dev/shm' => 'Program started from /dev/shm',
    'Programma\'s horen niet in het geheugen-bestandssysteem /dev/shm te staan. Malware zet zich daar neer omdat het na een herstart weg is.' => 'Programs don\'t belong in the memory file system /dev/shm. Malware puts itself there because it is gone after a reboot.',
    'Programma gestart vanuit /tmp' => 'Program started from /tmp',
    'Een programma uit /tmp of /var/tmp. Soms is dat een installatiescript, maar het is ook een bekende plek voor malware.' => 'A program from /tmp or /var/tmp. Sometimes that is an install script, but it is also a well-known place for malware.',
    'Verborgen programma gestart' => 'Hidden program started',
    'Een programma waarvan de naam met een punt begint (verborgen bestand). Gewone software doet dat niet; malware wel, om niet op te vallen.' => 'A program whose name starts with a dot (hidden file). Normal software doesn\'t do that; malware does, to stay unnoticed.',
    'Cryptominer' => 'Cryptominer',
    'Een programma dat cryptomunten delft (xmrig en dergelijke). Bijna altijd door een inbraak: het kost stroom en rekenkracht, en de inbreker zit nog op de server.' => 'A program that mines cryptocurrency (xmrig and the like). Almost always from a break-in: it costs power and computing time, and the intruder is still on the server.',
    'Sporen wissen: geschiedenis of logs' => 'Covering tracks: history or logs',
    'De shellgeschiedenis of logbestanden worden gewist of uitgezet. Een inbreker doet dat om zijn sporen te verbergen; soms is het gewoon onderhoud.' => 'The shell history or log files are wiped or disabled. An intruder does that to hide their tracks; sometimes it is just maintenance.',
    'Setuid-bit gezet' => 'Setuid bit set',
    'Een bestand krijgt het setuid-bit: wie het start, wordt eigenaar (vaak root). Een klassieke manier om root te blijven.' => 'A file gets the setuid bit: whoever starts it becomes the owner (often root). A classic way to stay root.',
    'SSH-sleutel toegevoegd via de opdrachtregel' => 'SSH key added from the command line',
    'Er wordt een sleutel aan authorized_keys toegevoegd met echo of tee. Daarmee kan iemand later zonder wachtwoord inloggen.' => 'A key is added to authorized_keys with echo or tee. With it, someone can later log in without a password.',
    'Uitbreken uit een container' => 'Container escape',
    'Een opdracht die vanuit een container de server zelf probeert over te nemen (nsenter naar proces 1, chroot naar /host, een container met de hele schijf erin).' => 'A command that tries to take over the server itself from inside a container (nsenter into process 1, chroot to /host, a container with the whole disk in it).',
    'Kernelmodule geladen vanuit een vreemde plek' => 'Kernel module loaded from an odd place',
    'Een kernelmodule uit /tmp, /dev/shm of een thuismap. Zo installeren rootkits zich; gewone modules komen uit /lib/modules.' => 'A kernel module from /tmp, /dev/shm or a home folder. That is how rootkits install themselves; normal modules come from /lib/modules.',
    '/etc/ld.so.preload gewijzigd' => '/etc/ld.so.preload changed',
    'Via /etc/ld.so.preload wordt code in élk programma geladen. Dat gebruiken bijna alleen rootkits.' => 'Through /etc/ld.so.preload code is loaded into every program. Almost only rootkits use that.',
    'Wijziging aan accounts, sudo, cron of systemd' => 'Change to accounts, sudo, cron or systemd',
    'Een bewaakt bestand werd gewijzigd: gebruikers, sudo-rechten, geplande taken of systemd-diensten. Zo nestelt een inbreker zich; bij onderhoud is het normaal.' => 'A watched file was changed: users, sudo rights, scheduled tasks or systemd services. That is how an intruder settles in; during maintenance it is normal.',
    'Shell of netcat maakt een verbinding naar buiten' => 'Shell or netcat connects to the outside',
    'Een shell, netcat of socat met een eigen verbinding naar internet. Dat is precies hoe een reverse shell eruitziet.' => 'A shell, netcat or socat with its own connection to the internet. That is exactly what a reverse shell looks like.',
    'Verbinding naar een typische aanvalspoort' => 'Connection to a typical attack port',
    'Een programma maakt verbinding met een poort die vooral door aanvalsgereedschap wordt gebruikt (4444, 1337, 31337 …).' => 'A program connects to a port mainly used by attack tools (4444, 1337, 31337 …).',
    'Verborgen programma neergezet' => 'Hidden program dropped',
    'Er staat ineens een programma (ELF) in /dev/shm of in een verborgen map in /tmp (bv. /tmp/.x/). Gewone software doet dat niet; malware wel, om niet op te vallen.' => 'A program (ELF) suddenly appears in /dev/shm or in a hidden folder in /tmp (e.g. /tmp/.x/). Normal software doesn\'t do that; malware does, to stay unnoticed.',
    'Nieuw programma in een tijdelijke map' => 'New program in a temporary folder',
    'Er staat ineens een uitvoerbaar programma (ELF) in /tmp of /var/tmp. Soms een installatieprogramma, maar ook de eerste stap van een inbraak: het gereedschap neerzetten.' => 'An executable program (ELF) suddenly appears in /tmp or /var/tmp. Sometimes an installer, but also the first step of a break-in: dropping the tools.',
    'Webshell neergezet' => 'Webshell dropped',
    'Een nieuw script in een webmap met code die opdrachten uitvoert (eval, system, base64_decode …). Dat is het kenmerk van een webshell.' => 'A new script in a web folder with code that runs commands (eval, system, base64_decode …). That is the hallmark of a webshell.',
    'Container gestart met volledige rechten' => 'Container started with full privileges',
    'Een container met --privileged of met de hele schijf van de server erin kan de server overnemen. Soms nodig, vaak niet.' => 'A container with --privileged or with the server\'s whole disk in it can take over the server. Sometimes needed, often not.',
    'Iemand opent een shell in een container' => 'Someone opens a shell in a container',
    'Er wordt een opdracht in een draaiende container uitgevoerd (podman/docker exec). Meestal jijzelf; buiten je eigen onderhoud is het verdacht.' => 'A command is run in a running container (podman/docker exec). Usually you; outside your own maintenance it is suspicious.',
    'SQL-injectie' => 'SQL injection',
    'Cross-site scripting (XSS)' => 'Cross-site scripting (XSS)',
    'Command injection' => 'Command injection',
    'Path traversal / bestanden lezen' => 'Path traversal / reading files',
    'PHP-wrapper / bestandsinclusie' => 'PHP wrapper / file inclusion',
    'Remote file inclusion' => 'Remote file inclusion',
    'Log4Shell (JNDI)' => 'Log4Shell (JNDI)',
    'Server-side request forgery' => 'Server-side request forgery',
    'Shellshock' => 'Shellshock',
    'Template-injectie' => 'Template injection',
    'PHP-code in het verzoek' => 'PHP code in the request',
    'OGNL/Struts-injectie' => 'OGNL/Struts injection',
    'PHPUnit eval-stdin (code uitvoeren)' => 'PHPUnit eval-stdin (code execution)',
    'Laravel Ignition (code uitvoeren)' => 'Laravel Ignition (code execution)',
    'Apache 2.4.49/50 path traversal' => 'Apache 2.4.49/50 path traversal',
    'Fortinet SSL-VPN bestanden lezen' => 'Fortinet SSL-VPN file read',
    'Pulse Secure VPN' => 'Pulse Secure VPN',
    'F5 BIG-IP iControl REST' => 'F5 BIG-IP iControl REST',
    'Cisco ASA/FTD bestanden lezen' => 'Cisco ASA/FTD file read',
    'Exchange ProxyShell' => 'Exchange ProxyShell',
    'Oracle WebLogic' => 'Oracle WebLogic',
    'Oracle WebLogic console' => 'Oracle WebLogic console',
    'Liferay Portal' => 'Liferay Portal',
    'ThinkPHP (code uitvoeren)' => 'ThinkPHP (code execution)',
    'Telerik UI' => 'Telerik UI',
    'D-Link HNAP (routers)' => 'D-Link HNAP (routers)',
    'GPON-routers (botnet)' => 'GPON routers (botnet)',
    'Boa-webserver van routers (botnet)' => 'Boa web server of routers (botnet)',
    'Mirai/Mozi-botnet (routers en camera\'s)' => 'Mirai/Mozi botnet (routers and cameras)',
    'Linksys TheMoon-worm' => 'Linksys TheMoon worm',
    'Netgear setup.cgi (botnet)' => 'Netgear setup.cgi (botnet)',
    'Spring Boot Actuator' => 'Spring Boot Actuator',
    'GeoServer (code uitvoeren)' => 'GeoServer (code execution)',
    'Zoekt naar .env (wachtwoorden en sleutels)' => 'Looking for .env (passwords and keys)',
    'Zoekt naar een .git-map (broncode)' => 'Looking for a .git folder (source code)',
    'Zoekt naar sleutels' => 'Looking for keys',
    'WordPress-login (wachtwoorden raden)' => 'WordPress login (password guessing)',
    'Zoekt naar phpMyAdmin' => 'Looking for phpMyAdmin',
    'Tomcat Manager (wachtwoorden raden)' => 'Tomcat Manager (password guessing)',
    'Docker-API van buiten' => 'Docker API from outside',
    'Apache server-status (informatie)' => 'Apache server-status (information)',
    'Xdebug op afstand' => 'Remote Xdebug',
    'Apache Solr' => 'Apache Solr',
    'Exchange/Outlook Web Access' => 'Exchange/Outlook Web Access',
    'OpenWrt/LuCI-routers' => 'OpenWrt/LuCI routers',
    'Jenkins script-console' => 'Jenkins script console',
    'Vreemde HTTP-methode' => 'Odd HTTP method',
    '🧬 Afwijkingen' => '🧬 Anomalies',
    '🧭 MITRE' => '🧭 MITRE',
    'Ook wat de regels kunnen zien' => 'Also what the rules can see',
    '🧬 Afwijkingen en ketens' => '🧬 Anomalies and chains',
    '<b>Afwijkingen melden</b> (RzMon leert per server wat normaal is)' => '<b>Report anomalies</b> (RzMon learns per server what is normal)',
    'Leerperiode (dagen)' => 'Learning period (days)',
    'Incident vanaf score' => 'Incident from score',
    '(lager: alleen op de pagina)' => '(lower: on the page only)',
    '<b>Ketens melden</b> (combinaties die samen op een aanval wijzen)' => '<b>Report chains</b> (combinations that together point to an attack)',
    'Venster voor een keten (minuten)' => 'Window for a chain (minutes)',
    '<b>Ingrijpen bij een keten</b> (aanvaller blokkeren; isoleren bij webshell of malware)' => '<b>Step in on a chain</b> (block the attacker; isolate on a webshell or malware)',
    'Een afwijking is iets wat de server in de leerperiode nooit deed; boven de score wordt het een incident (warning). Een keten is een combinatie, zoals webaanval → webshell, inloggen → achterdeur of binnenhalen → contact naar buiten; die is critical en gaat naar Pushover. Ingrijpen gebeurt alleen in de modus ⛔ Blokkeren. Alles staat op <i>🛡️ IDS → 🧬 Afwijkingen</i> en <i>🧭 MITRE</i>.' => 'An anomaly is something the server never did during the learning period; above the score it becomes an incident (warning). A chain is a combination, such as web attack → webshell, login → backdoor or download → contact with the outside; it is critical and goes to Pushover. Stepping in only happens in ⛔ Block mode. Everything is on <i>🛡️ IDS → 🧬 Anomalies</i> and <i>🧭 MITRE</i>.',
    'Nieuw programma: {exe}' => 'New program: {exe}',
    'Nieuw: {parent} start {child}' => 'New: {parent} starts {child}',
    'Nieuwe gebruiker voert programma\'s uit: {u}' => 'New user running programs: {u}',
    'Voor het eerst actief na inloggen: {u} (uid {uid})' => 'Active after login for the first time: {u} (uid {uid})',
    'Dienst maakt een nieuwe verbinding naar buiten: {exe} → {ip}:{p}' => 'Service makes a new outbound connection: {exe} → {ip}:{p}',
    'Nieuwe uitgaande verbinding: {exe} → poort {p}' => 'New outbound connection: {exe} → port {p}',
    'Eerste verbinding naar {cc}: {exe} → {ip}' => 'First connection to {cc}: {exe} → {ip}',
    'Nieuw programma luistert op het netwerk: {exe} (poort {p})' => 'New program listening on the network: {exe} (port {p})',
    'Luistert op een nieuwe poort: {exe} (poort {p})' => 'Listening on a new port: {exe} (port {p})',
    'Nieuw soort bestand: {path}' => 'New kind of file: {path}',
    'Nieuw: {exe} wijzigt {name}' => 'New: {exe} changes {name}',
    'Nieuw container-image: {img}' => 'New container image: {img}',
    'Nieuw in container {name}: {act}' => 'New in container {name}: {act}',
    'Afwijking: {what}' => 'Anomaly: {what}',
    'Nooit eerder gezien op deze server (geleerd sinds {d}).' => 'Never seen before on this server (learning since {d}).',
    'Deze server deed dit in de leerperiode nooit. Dat hoeft geen aanval te zijn (een nieuw programma, een update), maar past het niet bij wat je deed, kijk dan verder.' => 'This server never did this during the learning period. That need not be an attack (a new program, an update), but if it does not fit what you did, look further.',
    'Ongewoon veel nieuwe processen: {n} dit uur (normaal ~{avg})' => 'Unusually many new processes: {n} this hour (normally ~{avg})',
    'Ongewoon veel nieuwe verbindingen: {n} dit uur (normaal ~{avg})' => 'Unusually many new connections: {n} this hour (normally ~{avg})',
    'Actief op een ongewoon tijdstip: {u} om {h}:00' => 'Active at an unusual time: {u} at {h}:00',
    'Login van {user} vanaf {from} ({ip}), waar net een aanval was' => 'Login by {user} from {from} ({ip}), where there was just an attack',
    'Keten: {what}' => 'Chain: {what}',
    'overig' => 'other',
    'Signaal' => 'Signal',
    'Deze server deed iets wat hij in de leerperiode nooit deed: {what}.' => 'This server did something it never did during the learning period: {what}.',
    'Meestal onschuldig: nieuwe software, een update of iets wat je zelf instelde. Verdacht als niemand iets veranderde, of als er tegelijk andere meldingen zijn (zie Ketens).' => 'Usually harmless: new software, an update or something you set up yourself. Suspicious if nobody changed anything, or if there are other alerts at the same time (see Chains).',
    'Was jij dit of een update? Klik "Ja, dit was ik". Het is al geleerd: het wordt niet nog eens gemeld.' => 'Was it you or an update? Click "Yes, this was me". It has already been learned: it will not be reported again.',
    'Niet: kijk bij het bewijs welk programma het was, wie het startte en waar het mee verbindt.' => 'If not: check the evidence for which program it was, who started it and what it connects to.',
    'Laat de server na een grote wijziging opnieuw leren (IDS → Afwijkingen), dan blijft de lijst rustig.' => 'Let the server learn again after a big change (IDS → Anomalies), so the list stays quiet.',
    'Meerdere dingen kort na elkaar die samen het verloop van een aanval vormen. De stappen staan hieronder, in volgorde.' => 'Several things shortly after each other that together form the course of an attack. The steps are below, in order.',
    'Ernstig: ga uit van een inbraak tot je elke stap kunt verklaren.' => 'Serious: assume a break-in until you can explain every step.',
    'Verdacht: elke stap los kan onschuldig zijn, samen is het de moeite van controleren waard.' => 'Suspicious: each step on its own may be harmless, together it is worth checking.',
    'Loop de stappen na: klik op een stap om het incident erbij te openen.' => 'Go through the steps: click a step to open its incident.',
    'Kun je ze niet verklaren: isoleer de server, verander wachtwoorden en SSH-sleutels, en zoek uit hoe het binnenkwam.' => 'If you cannot explain them: isolate the server, change passwords and SSH keys, and find out how it got in.',
    'Was jij het: klik "Ja, dit was ik". Deze soort keten wordt dan voor deze server niet meer gemeld.' => 'If it was you: click "Yes, this was me". This kind of chain will then no longer be reported for this server.',
    'Wie is er ingelogd, en sinds wanneer' => 'Who is logged in, and since when',
    'Gebruik SSH-sleutels in plaats van wachtwoorden, houd alles bijgewerkt en laat RzMon in de modus Blokkeren staan.' => 'Use SSH keys instead of passwords, keep everything updated and leave RzMon in Block mode.',
    'Leren nu afronden? Vanaf nu meldt RzMon alles wat deze server nog niet deed.' => 'Finish learning now? From now on RzMon reports everything this server has not done before.',
    'Opnieuw leren? Alles wat RzMon over deze server geleerd heeft, gaat weg; de komende dagen wordt er niets als afwijking gemeld.' => 'Learn again? Everything RzMon learned about this server is removed; nothing will be reported as an anomaly for the coming days.',
    'Leren afgerond' => 'Learning finished',
    'De server leert opnieuw' => 'The server is learning again',
    'Verkennen' => 'Reconnaissance',
    'Voorbereiden' => 'Preparation',
    'Binnenkomen' => 'Getting in',
    'Uitvoeren' => 'Execution',
    'Blijven' => 'Staying (persistence)',
    'Rechten verhogen' => 'Privilege escalation',
    'Verbergen' => 'Hiding',
    'Beveiliging uitschakelen' => 'Disabling defences',
    'Wachtwoorden stelen' => 'Stealing credentials',
    'Rondkijken' => 'Looking around',
    'Verder het netwerk in' => 'Moving through the network',
    'Verzamelen' => 'Collection',
    'Op afstand besturen' => 'Remote control',
    'Gegevens weghalen' => 'Taking data out',
    'Schade' => 'Damage',
    'Score: hoe ongewoon (0–100)' => 'Score: how unusual (0–100)',
    'afwijking' => 'anomaly',
    'regel' => 'rule',
    'Afwijkingen staan uit (Instellingen → IDS → Endpoint-bewaking)' => 'Anomalies are off (Settings → IDS → Endpoint monitoring)',
    'Wat is normaal? (leren per server)' => 'What is normal? (learning per server)',
    'Elke server leert {d} dagen wat normaal is: welke programma\'s, gebruikers, verbindingen en poorten. Daarna meldt RzMon wat die server nog nooit deed. Na een grote wijziging (nieuwe software) kun je hem opnieuw laten leren.' => 'Each server learns for {d} days what is normal: which programs, users, connections and ports. After that RzMon reports what that server has never done. After a big change (new software) you can let it learn again.',
    'Geleerd' => 'Learned',
    'Afwijkingen (7 dagen)' => 'Anomalies (7 days)',
    'dag {n} van {d}' => 'day {n} of {d}',
    'klaar, meldt sinds {t}' => 'done, reporting since {t}',
    '{n} kenmerken' => '{n} traits',
    'Leren afronden' => 'Finish learning',
    'Opnieuw leren' => 'Learn again',
    'Nog geen servers met endpoint-bewaking (agent 1.63.0 of nieuwer, en aan in de Agent Manager).' => 'No servers with endpoint monitoring yet (agent 1.63.0 or newer, and on in the Agent Manager).',
    'Ketens' => 'Chains',
    '(laatste 30 dagen)' => '(last 30 days)',
    'Ketens staan uit (Instellingen → IDS → Endpoint-bewaking).' => 'Chains are off (Settings → IDS → Endpoint monitoring).',
    '{n}× gegroeid' => 'grew {n}×',
    'Geen ketens 👌' => 'No chains 👌',
    'Welke ketens herkent RzMon?' => 'Which chains does RzMon recognise?',
    'Afwijkingen' => 'Anomalies',
    '(vanaf score {n} ook een incident)' => '(from score {n} also an incident)',
    'Geen afwijkingen 👌' => 'No anomalies 👌',
    'Nog niets: de servers zijn nog aan het leren.' => 'Nothing yet: the servers are still learning.',
    'Alles wat RzMon de laatste {d} dagen zag (regels, afwijkingen en IDS-meldingen), gerangschikt naar de stappen van een aanval volgens MITRE ATT&CK. Klik op een techniek voor de meldingen.' => 'Everything RzMon saw in the last {d} days (rules, anomalies and IDS alerts), arranged by the steps of an attack according to MITRE ATT&CK. Click a technique for the alerts.',
    'Niets gezien 👌' => 'Nothing seen 👌',
    '{n} regel(s) kunnen dit zien' => '{n} rule(s) can see this',
    'Stap: {t}' => 'Step: {t}',
    'uitleg bij MITRE' => 'explanation at MITRE',
    'Geen meldingen in deze periode. Deze regels kunnen het zien:' => 'No alerts in this period. These rules can see it:',
    'Afwijking' => 'Anomaly',
    'WordPress File Manager: bestanden uploaden zonder inloggen' => 'WordPress File Manager: upload files without logging in',
    'Webaanval gevolgd door code op de webserver' => 'Web attack followed by code on the web server',
    'Eerst een aanval op een website, daarna voert de webserver iets uit of komt er een bestand in de webmap. Waarschijnlijk is de aanval gelukt (webshell).' => 'First an attack on a website, then the web server runs something or a file appears in the web folder. The attack probably succeeded (webshell).',
    'Inloggen gevolgd door rechten of een achterdeur' => 'Login followed by privileges or a backdoor',
    'Iemand logde in en kort daarna veranderden er rechten, accounts of iets dat blijft na een herstart (cron, systemd, SSH-sleutels). Was jij dit niet, dan zit er iemand op de server.' => 'Someone logged in and shortly after, privileges, accounts or something that survives a restart (cron, systemd, SSH keys) changed. If this was not you, someone is on the server.',
    'Programma binnengehaald en daarna contact naar buiten' => 'Program downloaded, then contact with the outside',
    'Er kwam een programma binnen en kort daarna maakte de server een nieuwe verbinding naar buiten. Zo werken malware en cryptominers.' => 'A program came in and shortly after the server made a new outbound connection. That is how malware and cryptominers work.',
    'Meerdere stappen van een aanval' => 'Several steps of an attack',
    'Binnen korte tijd gebeurden er dingen die bij verschillende stappen van een aanval horen (MITRE ATT&CK-tactieken). Los misschien onschuldig, samen verdacht.' => 'Within a short time things happened that belong to different steps of an attack (MITRE ATT&CK tactics). Perhaps harmless on their own, suspicious together.',
    'Veel afwijkingen tegelijk' => 'Many anomalies at once',
    'De server deed in korte tijd veel dingen die hij nooit eerder deed. Dat kan een grote update of nieuwe software zijn, maar ook iemand die rondkijkt.' => 'The server did many things in a short time that it never did before. That can be a big update or new software, but also someone looking around.',
    'Mogelijk verder het netwerk in' => 'Possibly moving through the network',
    'Er werd ingelogd vanaf een andere eigen server waar net een aanval of keten was. Een aanvaller gebruikt een gehackte server vaak om verder te komen.' => 'Someone logged in from another of your own servers where there was just an attack or chain. An attacker often uses a hacked server to get further.',
    'Leren afgerond (afwijkingen)' => 'Learning finished (anomalies)',
    'Opnieuw leren (afwijkingen)' => 'Learning again (anomalies)',
    'Dreigingsinformatie' => 'Threat intelligence',
    'RzMon vraagt na wat er op internet bekend is over de IP-adressen en bestanden uit je incidenten: is dit een bekende aanvaller, een onschuldige scanner, een Tor-uitgang, bekende malware? Dat staat dan bij het incident en bij het IP-adres, en RzMon handelt ernaar. Er gaat alleen het IP-adres of de hash van een bestand naar buiten, nooit namen van servers of gebruikers. Werkt alleen als het IDS aan staat.' => 'RzMon looks up what is known on the internet about the IP addresses and files in your incidents: is this a known attacker, a harmless scanner, a Tor exit, known malware? That is then shown with the incident and the IP address, and RzMon acts on it. Only the IP address or a file\'s hash leaves your network, never names of servers or users. Only works when the IDS is on.',
    '<b>Dreigingsinformatie aan</b>' => '<b>Threat intelligence on</b>',
    '(gratis: <a href="https://www.abuseipdb.com/account/api" target="_blank" rel="noopener">abuseipdb.com → Account → API</a>; 1.000 opzoekingen per dag)' => '(free: <a href="https://www.abuseipdb.com/account/api" target="_blank" rel="noopener">abuseipdb.com → Account → API</a>; 1,000 lookups per day)',
    'plak hier je sleutel' => 'paste your key here',
    'Sleutel testen' => 'Test key',
    '<b>Melden</b> bij AbuseIPDB wie RzMon automatisch blokkeert (brute force, webaanval, honeypot; hooguit één keer per dag per IP)' => '<b>Report</b> to AbuseIPDB whoever RzMon blocks automatically (brute force, web attack, honeypot; at most once a day per IP)',
    'Dan gaan het IP-adres, de soort aanval en de tekst "RzMon IDS" naar AbuseIPDB, zodat anderen die aanvaller ook kunnen weren. Nooit adressen uit je eigen netwerk of van de whitelist.' => 'The IP address, the kind of attack and the text "RzMon IDS" then go to AbuseIPDB, so others can block that attacker too. Never addresses from your own network or the whitelist.',
    'Andere bronnen (gratis)' => 'Other sources (free)',
    '<b>GreyNoise</b> (scant dit IP het hele internet, is het een bekende dienst zoals Google of Shodan, of kwaadaardig)' => '<b>GreyNoise</b> (does this IP scan the whole internet, is it a known service like Google or Shodan, or malicious)',
    'GreyNoise-sleutel' => 'GreyNoise key',
    '(niet nodig; zonder sleutel ongeveer 50 per dag)' => '(not needed; about 50 a day without a key)',
    '<b>Shodan InternetDB</b> (open poorten, lekken en labels zoals c2 of malware van het IP zelf)' => '<b>Shodan InternetDB</b> (open ports, vulnerabilities and tags such as c2 or malware of the IP itself)',
    '<b>CIRCL hashlookup</b> (is een nieuw programma een bekend, goed bestand)' => '<b>CIRCL hashlookup</b> (is a new program a known, good file)',
    '<b>Tor-uitgangen</b> herkennen (dagelijkse lijst)' => 'Recognise <b>Tor exits</b> (daily list)',
    'Tor-uitgangen ook <b>vooraf blokkeren</b> op de servers (modus Blokkeren, bij de bekende aanvallers)' => 'Also <b>block Tor exits in advance</b> on the servers (Block mode, with the known attackers)',
    '<b>abuse.ch Feodo Tracker</b> (botnet-servers bij de bekende aanvallers; een verbinding ernaartoe is critical)' => '<b>abuse.ch Feodo Tracker</b> (botnet servers with the known attackers; a connection to one is critical)',
    '<b>abuse.ch URLhaus</b> (domeinen met malware, voor de DNS-controle via AdGuard)' => '<b>abuse.ch URLhaus</b> (domains with malware, for the DNS check via AdGuard)',
    'abuse.ch Auth-Key' => 'abuse.ch Auth-Key',
    '(gratis: <a href="https://auth.abuse.ch/" target="_blank" rel="noopener">auth.abuse.ch</a>; voor MalwareBazaar en ThreatFox)' => '(free: <a href="https://auth.abuse.ch/" target="_blank" rel="noopener">auth.abuse.ch</a>; for MalwareBazaar and ThreatFox)',
    'Wat RzMon ermee doet' => 'What RzMon does with it',
    '<b>Bekende aanvallers blokkeren</b> (modus ⛔ Blokkeren), vanaf deze score:' => '<b>Block known attackers</b> (⛔ Block mode), from this score:',
    'Score voor "bekende aanvaller" (0–100)' => 'Score for "known attacker" (0–100)',
    '(AbuseIPDB-percentage, of 80–90 bij GreyNoise/Shodan/abuse.ch)' => '(AbuseIPDB percentage, or 80–90 for GreyNoise/Shodan/abuse.ch)',
    'Een <b>login</b> vanaf een bekende aanvaller wordt critical (Pushover)' => 'A <b>login</b> from a known attacker becomes critical (Pushover)',
    'Een webaanval van een <b>onschuldige scanner</b> (GreyNoise) vanzelf afhandelen' => 'Close a web attack from a <b>harmless scanner</b> (GreyNoise) automatically',
    'Een webaanval op een <b>lek dat de server echt heeft</b> (tabblad Kwetsbaarheden) is critical' => 'A web attack on a <b>vulnerability the server really has</b> (Vulnerabilities tab) is critical',
    'Lijsten nu bijwerken' => 'Update lists now',
    'Bronnen: AbuseIPDB, GreyNoise Community, Shodan InternetDB, CIRCL hashlookup, abuse.ch (Feodo Tracker, URLhaus, ThreatFox, MalwareBazaar), Tor Project. Opzoeken gaat op de achtergrond (cron), met een cache van een dag en een limiet per dag.' => 'Sources: AbuseIPDB, GreyNoise Community, Shodan InternetDB, CIRCL hashlookup, abuse.ch (Feodo Tracker, URLhaus, ThreatFox, MalwareBazaar), Tor Project. Lookups run in the background (cron), with a one-day cache and a daily limit.',
    'Verbinding met een bekende aanvaller: {exe} → {ip}' => 'Connection to a known attacker: {exe} → {ip}',
    'Verbinding met een bekende aanvaller' => 'Connection to a known attacker',
    'Dit adres staat op een lijst met botnet- en malwareservers ({list}). Een programma op de server praat ermee: meestal malware die opdrachten ophaalt.' => 'This address is on a list of botnet and malware servers ({list}). A program on the server talks to it: usually malware fetching commands.',
    'Een programma op deze server had contact met {ip}, een adres dat bekendstaat als aanvaller of botnet-server (zie hieronder waarom).' => 'A program on this server had contact with {ip}, an address known as an attacker or botnet server (see below why).',
    'Ernstig: meestal malware die opdrachten ophaalt of gegevens wegstuurt. Soms vals alarm, bijvoorbeeld een gedeeld cloud-adres.' => 'Serious: usually malware fetching commands or sending data out. Sometimes a false alarm, for example a shared cloud address.',
    'Kijk bij het bewijs welk programma het was en waar het staat.' => 'Check the evidence for which program it was and where it is.',
    'Herken je het niet: stop het, isoleer de server en zoek uit hoe het binnenkwam.' => 'If you do not recognise it: stop it, isolate the server and find out how it got in.',
    'Zet "uitgaand naar bekende aanvallers blokkeren" aan bij IDS → Aanvallers en verkeer.' => 'Turn on "block outbound to known attackers" under IDS → Attackers and traffic.',
    'Er kwam een bestand op de server dat bekendstaat als malware.' => 'A file known as malware appeared on the server.',
    'Ernstig: ga ervan uit dat iemand op de server kon komen of dat een programma het binnenhaalde.' => 'Serious: assume someone could get onto the server or a program downloaded it.',
    'Verwijder het bestand niet meteen: kijk eerst wie het maakte (Live, auditd) en of het draait.' => 'Do not delete the file right away: first check who created it (Live, auditd) and whether it is running.',
    'Isoleer de server, stop het proces en verwijder het bestand.' => 'Isolate the server, stop the process and delete the file.',
    'Zoek uit hoe het binnenkwam (webaanval, gestolen wachtwoord) en verander wachtwoorden en sleutels.' => 'Find out how it got in (web attack, stolen password) and change passwords and keys.',
    'Waar staat het bestand?' => 'Where is the file?',
    'Zet /tmp en /dev/shm op noexec en houd alles bijgewerkt.' => 'Mount /tmp and /dev/shm noexec and keep everything updated.',
    'Iemand probeerde een lek dat deze server volgens de kwetsbaarheden-scan echt heeft. Zo\'n aanval kan dus lukken.' => 'Someone tried a vulnerability that, according to the vulnerability scan, this server really has. Such an attack can therefore succeed.',
    'Ernstig, zeker als een verzoek een gewoon antwoord (2xx) kreeg.' => 'Serious, especially if a request got a normal response (2xx).',
    'Werk het pakket meteen bij (tabblad Kwetsbaarheden).' => 'Update the package right away (Vulnerabilities tab).',
    'Kijk of er daarna iets gebeurde (IDS → Afwijkingen en Ketens).' => 'Check whether anything happened afterwards (IDS → Anomalies and Chains).',
    'Zet automatische beveiligingsupdates aan, of werk wekelijks bij via de agent.' => 'Turn on automatic security updates, or update weekly via the agent.',
    'Aanval op een lek dat deze server heeft: {cve} vanaf {ip}' => 'Attack on a vulnerability this server has: {cve} from {ip}',
    '{pkg} {ver} heeft dit lek{fix}. Werk het bij (tabblad Kwetsbaarheden) en kijk of de aanval lukte.' => '{pkg} {ver} has this vulnerability{fix}. Update it (Vulnerabilities tab) and check whether the attack succeeded.',
    '(opgelost in {v})' => '(fixed in {v})',
