    'geen YARA' => 'no YARA',
    'Suricata zonder eve.json' => 'Suricata without eve.json',
    'Verkeer' => 'Traffic',
    'YARA: bekende malware of webshell' => 'YARA: known malware or webshell',
    'Een nieuw bestand lijkt volgens de YARA-regels van RzMon op malware: een webshell, cryptominer, reverse shell, IoT-botnet, Kinsing of een rootkit. De naam van de regel staat bij het bewijs.' => 'According to RzMon\'s YARA rules, a new file looks like malware: a webshell, cryptominer, reverse shell, IoT botnet, Kinsing or a rootkit. The rule\'s name is in the evidence.',
    'YARA: verdacht bestand' => 'YARA: suspicious file',
    'Een nieuw bestand is ingepakt of sterk versleuteld (UPX, lange base64). Malware doet dat vaak om niet op te vallen, maar sommige gewone software ook.' => 'A new file is packed or heavily obfuscated (UPX, long base64). Malware often does this to stay hidden, but some ordinary software does too.',
    'Melding' => 'Notification',
    '<b>Suricata</b> (alerts van de agents gebruiken, als Suricata op een server draait; agent 1.64.0)' => '<b>Suricata</b> (use alerts from the agents, if Suricata runs on a server; agent 1.64.0)',
    '<b>Blokkeren</b> bij een ernstig Suricata-alert (ernst 1, aanvaller van buiten, modus Blokkeren)' => '<b>Block</b> on a serious Suricata alert (severity 1, outside attacker, Block mode)',
    '<b>YARA</b> (regels van RzMon naar de agents sturen: nieuwe bestanden op webshells, miners, botnets en rootkits controleren; YARA moet op de server staan)' => '<b>YARA</b> (send RzMon\'s rules to the agents: check new files for webshells, miners, botnets and rootkits; YARA must be installed on the server)',
    'Toegestaan tonen (RzMon zelf)' => 'Show allowed (RzMon itself)',
