    'Een IP met een score van {n} of hoger (AbuseIPDB-percentage, of 80–90 bij GreyNoise, Shodan en abuse.ch).' => 'An IP with a score of {n} or higher (AbuseIPDB percentage, or 80–90 for GreyNoise, Shodan and abuse.ch).',
