    'DNS-controle' => 'DNS check',
    'Een geslaagde SSH-login van buiten je netwerk, vanaf een IP dat hier nooit inlogde, of als root.' => 'A successful SSH login from outside your network, from an IP that never logged in here, or as root.',
    'Een geslaagde login vanaf een IP dat AbuseIPDB, GreyNoise of de lijsten als aanvaller kennen.' => 'A successful login from an IP that AbuseIPDB, GreyNoise or the lists know as an attacker.',
    'Een geslaagde login vanaf een IP dat net veel mislukte pogingen deed.' => 'A successful login from an IP that just made many failed attempts.',
    'Een inlog met een naam die niet bestaat (admin, test …) of een verbinding naar de honeypot-poort: dat doen alleen aanvallers.' => 'A login with a name that does not exist (admin, test …) or a connection to the honeypot port: only attackers do that.',
    'Een instelling van de server werd minder veilig (SSH, firewall, updates …).' => 'A server setting became less secure (SSH, firewall, updates …).',
    'Een nieuw bestand dat YARA of MalwareBazaar als malware herkent.' => 'A new file that YARA or MalwareBazaar recognises as malware.',
    'Een programma praat met een adres op de lijsten (Feodo, ThreatFox, Spamhaus …).' => 'A program talks to an address on the lists (Feodo, ThreatFox, Spamhaus …).',
    'Een shell die naar buiten belt, of een programma dat cryptomunten maakt.' => 'A shell that calls out, or a program that mines cryptocurrency.',
    'Een shell in een container, een container met volledige rechten, of uitbreken naar de server.' => 'A shell in a container, a container with full privileges, or escaping to the server.',
    'Een verzoek via SWAG met een aanval erin: SQL-injectie, XSS, Log4Shell, path traversal, bekende exploits …' => 'A request via SWAG with an attack in it: SQL injection, XSS, Log4Shell, path traversal, known exploits …',
    'Een webaanval met een CVE die volgens de kwetsbaarheden-scan op deze server openstaat.' => 'A web attack with a CVE that, according to the vulnerability scan, is open on this server.',
    'Een webaanval van een bekende, onschuldige scanner (GreyNoise: Shodan, Censys …).' => 'A web attack from a known, harmless scanner (GreyNoise: Shodan, Censys …).',
    'Een webserver die een shell start, of een nieuw script met webshell-code in een webmap.' => 'A web server that starts a shell, or a new script with webshell code in a web folder.',
    'Elk apparaat: domeinen van malware of phishing, DNS-tunnels en verzonnen domeinen.' => 'Every device: malware or phishing domains, DNS tunnels and made-up domains.',
    'Het IP van een incident is volgens AbuseIPDB, GreyNoise, Shodan of abuse.ch een aanvaller.' => 'The IP of an incident is an attacker according to AbuseIPDB, GreyNoise, Shodan or abuse.ch.',
